(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,830339,e=>{"use strict";let t={"academic-coauthor-chase":{id:"academic-coauthor-chase",agentSlug:"town-academic-coauthor-chase",version:2,name:"Co-Author Chase",description:"Twice each weekday, re-reads the threads where you asked a collaborator for a section, a figure, a dataset, an analysis, or an approval to submit, keeps only the asks that have gone quiet past the window you set, and ranks them by the date they hold up. It writes one nudge per person and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"academic-grant-deadline-watch":{id:"academic-grant-deadline-watch",agentSlug:"town-academic-grant-deadline-watch",version:2,name:"Grant Deadline Watch",description:"Twice a week, reads the mail from sponsors, program officers, and your research office for the proposal, report, and compliance dates you are working toward, and names every piece each one still needs and who it has to come from. It writes one request per person on each obligation and leaves it unsent; switch to report-only if you just want what is missing. It never files anything with a sponsor.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"academic-manuscript-revision-clock":{id:"academic-manuscript-revision-clock",agentSlug:"town-academic-manuscript-revision-clock",version:2,name:"Manuscript Revision Clock",description:"Twice a week, rebuilds every manuscript you have in flight from the editorial correspondence itself and reports the two things that quietly cost a publication: the date you agreed to and stopped counting, and the submission a journal has held far past the window it stated. It keeps one log of the pipeline and holds every write for your approval.",verified:!0,hidden:!0,requirements:["google"]},"academic-peer-review-queue":{id:"academic-peer-review-queue",agentSlug:"town-academic-peer-review-queue",version:2,name:"Peer Review Queue",description:"Once a week, rebuilds every review you agreed to write and every invitation you have not answered, ranks them by the date the editor gave, and shows which ones an editor has already reminded you about. It writes one reply per invitation that has gone stale and leaves it unsent; switch to report-only if you just want the queue. It never opens or repeats the work under review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"academic-research-meeting-actions":{id:"academic-research-meeting-actions",agentSlug:"town-academic-research-meeting-actions",version:2,name:"Research Meeting Actions",description:"About an hour after a research meeting on your calendar ends, rebuilds only the commitments the meeting actually produced, splits what you took on from what everyone else took on, and sends the list privately to you. It is a record for you alone: nothing is drafted to the people who were in the room, and a meeting that is not research work is skipped in silence.",verified:!0,hidden:!0,requirements:["google"]},"advisor-client-document-chase":{id:"advisor-client-document-chase",agentSlug:"town-advisor-client-document-chase",version:2,name:"Client Document Chase",description:"Twice each weekday, rebuilds what you asked each client to send and checks your mail for what actually came back, so the paperwork loop is one list instead of a memory test. Turn reminders on and it saves one unsent note per client covering every item still open, with no rate, amount, or recommendation anywhere in it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"advisor-pending-case-watch":{id:"advisor-pending-case-watch",agentSlug:"town-advisor-pending-case-watch",version:2,name:"Pending Case Watch",description:"Twice each weekday, rebuilds the cases you have sitting with a third party from their own messages and separates the two that cost you time: the case nobody has acknowledged, and the case that has gone quiet past your waiting window. Turn asks on and it writes one status request per case and leaves it unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"advisor-post-meeting-next-steps":{id:"advisor-post-meeting-next-steps",agentSlug:"town-advisor-post-meeting-next-steps",version:2,name:"Post-Meeting Next Steps",description:"About an hour after a client meeting on your calendar ends, the invite, the thread behind it, and any recording you kept are read for one thing only: what each side agreed to do next. One unsent note is drafted to the client listing their steps and yours with the dates that were said out loud. It restates no advice, no figures, and no recommendation, and a calendar entry that was not a client meeting is skipped in silence.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"advisor-quiet-client-sweep":{id:"advisor-quiet-client-sweep",agentSlug:"town-advisor-quiet-client-sweep",version:2,name:"Quiet Client Sweep",description:"Every Tuesday morning, walks the clients in your mail and calendar and measures one thing: how long since either of you said anything. The ones past your silence window come back ranked, with the reason each one rose to the top. Turn check-ins on and it saves one unsent note per client that asks how things are and sells nothing.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"advisor-renewal-cycle-register":{id:"advisor-renewal-cycle-register",agentSlug:"town-advisor-renewal-cycle-register",version:2,name:"Renewal Cycle Register",description:"Every Monday and Thursday morning, rebuilds the dated obligations your book is carrying from the notices, confirmations, and invitations already in your mail and calendar, and delivers them as one register ranked by days left. It reports and nothing else: no reminders, no client messages, and no opinion about what any of it is worth.",verified:!0,hidden:!0,requirements:["google"]},"agency-approval-chase":{id:"agency-approval-chase",agentSlug:"town-agency-approval-chase",version:2,name:"Client Approval Chase",description:"You get the overdue list plus drafted nudges.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"agency-client-monthly-report":{id:"agency-client-monthly-report",agentSlug:"town-agency-client-monthly-report",version:2,name:"Monthly Client Report",description:"You get the numbers, the trend, and the recommendation.",verified:!0,hidden:!0,requirements:["google"]},"agency-client-request-routing":{id:"agency-client-request-routing",agentSlug:"town-agency-client-request-routing",version:2,name:"Client Request Hand-Off",description:"Nothing waits for you to reread the thread.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"agency-proposal-followup-sequence":{id:"agency-proposal-followup-sequence",agentSlug:"town-agency-proposal-followup-sequence",version:2,name:"Proposal Follow-Up Chaser",description:"You send a fresh angle, not another bump.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"agency-retainer-scope-watch":{id:"agency-retainer-scope-watch",agentSlug:"town-agency-retainer-scope-watch",version:2,name:"Scope Creep Watch",description:"You learn which accounts cost more than they pay.",verified:!0,hidden:!0,requirements:["google"]},"auto-inbox":{id:"auto-inbox",agentSlug:"town-auto-inbox",version:85,name:"Auto-inbox",description:"Keeps your inbox organized without the work. Labels new mail, drafts replies, and helps with scheduling.",verified:!0,requirements:["google"],subagentSlugs:["town-auto-inbox-labeler","town-auto-email-response","town-auto-scheduler","town-email-criteria-triager","town-scheduling-signal-extractor","town-scheduling-ask"]},"auto-outbox":{id:"auto-outbox",agentSlug:"town-auto-outbox",version:3,name:"Auto-outbox",description:"Watches emails you send and keeps your scheduling sessions in sync with what you did manually.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:["town-email-criteria-triager","town-scheduling-reconciler"]},"briefing-topic-suggestion-engine":{id:"briefing-topic-suggestion-engine",agentSlug:"town-briefing-topic-suggestion-engine",version:15,name:"Briefing Topic Suggestion Engine",description:"Quickly scans user data to suggest personalized topics for the morning briefing. Optimized for speed during onboarding.",verified:!0,adminOnly:!0,requirements:["google"]},"calendar-enrichment":{id:"calendar-enrichment",agentSlug:"town-calendar-enrichment",version:14,name:"Calendar Review",description:"Keeps a judged understanding of your upcoming calendar events current, so other routines read a pre-understood schedule",verified:!0,adminOnly:!0,requirements:["google"],subagentSlugs:[]},"campaign-coalition-call-commitments":{id:"campaign-coalition-call-commitments",agentSlug:"town-campaign-coalition-call-commitments",version:2,name:"Coalition Call Commitments",description:"About an hour after a coordination call with partner organizations, allies, venues, or vendors ends, establishes what that call actually was, then pulls out only the logistics each side took on: who is doing what, by when, at which address, with which materials. It saves one short follow-up in the thread the call came from, addressed to the people who were already on the invite, and leaves it unsent. Strategy, message, and targeting discussion is left where it was said.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"campaign-filing-deadline-tracker":{id:"campaign-filing-deadline-tracker",agentSlug:"town-campaign-filing-deadline-tracker",version:2,name:"Filing Deadline Tracker",description:"Each weekday morning, keeps one dated list of every filing, reporting, and registration deadline your own mail, calendar, and settings name, with the source beside each date and the days remaining counted from today. It tracks dates and nothing else: it never tells you what to file, never interprets a rule, never prepares or reviews a submission, and never contacts anyone.",verified:!0,hidden:!0,requirements:["google"]},"campaign-partner-confirmation-chase":{id:"campaign-partner-confirmation-chase",agentSlug:"town-campaign-partner-confirmation-chase",version:2,name:"Partner Confirmation Chase",description:"Late each morning and again in the afternoon on weekdays, rereads the coordination threads you have open with partner organizations, venues, and vendors, and keeps only the ones where you asked for something, nobody answered, and a date on your calendar depends on the answer. It writes one short nudge per thread that carries an open ask, replying in that thread, and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"campaign-shift-coverage-chase":{id:"campaign-shift-coverage-chase",agentSlug:"town-campaign-shift-coverage-chase",version:2,name:"Shift Coverage Chase",description:"Twice each weekday, rebuilds the shifts sitting on your calendar and in your sign-up threads for the days ahead, then separates the people who said yes in their own words from the ones who signed up and went quiet. It writes one short confirmation ask per quiet person, replying inside the thread they are already on, and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"campaign-weekly-logistics-recap":{id:"campaign-weekly-logistics-recap",agentSlug:"town-campaign-weekly-logistics-recap",version:2,name:"Weekly Logistics Recap",description:"Each Friday afternoon, rebuilds the operating week from your own calendar and mail: what ran and what it left open, how staffing landed against what was planned, which dated items are coming, and which partner threads are still unanswered. It saves one private write-up you can edit and pass on, and it sends nothing to anyone.",verified:!0,hidden:!0,requirements:["google"]},"clinic-authorization-chaser":{id:"clinic-authorization-chaser",agentSlug:"town-clinic-authorization-chaser",version:2,name:"Authorization Chaser",description:"Twice a week, reconstructs every authorization, pre-certification, and benefit check you have submitted, works out which ones the payer has gone quiet on or which expire soon, refreshes your pending-authorization log, and drafts the status-check emails so the follow-up is one approval away.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"clinic-credential-expiry-guard":{id:"clinic-credential-expiry-guard",agentSlug:"town-clinic-credential-expiry-guard",version:2,name:"Credential Expiry Register",description:"Twice a week, reconciles your credentialing tracker with the renewal notices, certificates, and payer letters sitting in mail and Drive, keeps one private roster of every expiration date per clinician, and alerts you while there is still time to act.",verified:!0,hidden:!0,requirements:["google"]},"clinic-referral-intake-response":{id:"clinic-referral-intake-response",agentSlug:"town-clinic-referral-intake-response",version:2,name:"Referral Response Drafts",description:"Three times a day, finds the new referrals and intake requests sitting in the practice inbox, checks each one against the insurance panels you accept and the scope you actually treat, drafts the acceptance or the redirect, and keeps a running log of every referral and what happened to it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"clinic-scheduling-reply-drafts":{id:"clinic-scheduling-reply-drafts",agentSlug:"town-clinic-scheduling-reply-drafts",version:3,name:"Scheduling Reply Drafts",description:"A few times a day, finds the scheduling threads still waiting on you, reads the provider's actual calendar, and saves a reply offering specific open appointment times in the right timezone and your practice's usual format. Every reply stays an unsent draft you approve.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"clinic-weekly-practice-update":{id:"clinic-weekly-practice-update",agentSlug:"town-clinic-weekly-practice-update",version:2,name:"Weekly Practice Update",description:"Early Monday, rebuilds last week from the schedule, the referral log, and the credentialing and authorization queues, then leaves a private draft of the practice update in the format your owner or medical director already expects, with every number labeled by where it came from.",verified:!0,hidden:!0,requirements:["google"]},"coaching-hours-log":{id:"coaching-hours-log",agentSlug:"town-coaching-hours-log",version:3,name:"Coaching Hours Log",description:"Early each month, reconstructs last month's delivered sessions from your calendar into a credential-ready log: client, date, duration, individual or group, paid or pro bono, with running totals and unique client counts. Kept as a Town document, and appended to your own tracker only after you approve the rows.",verified:!0,hidden:!0,requirements:["google"]},"coaching-package-renewal-timing":{id:"coaching-package-renewal-timing",agentSlug:"town-coaching-package-renewal-timing",version:3,name:"Renewal Timing Watch",description:"Every Wednesday, counts the sessions each client has actually used against the package or retainer they bought, flags the engagements that are close to running out or close to expiring, and drafts the renewal opener for each one so the conversation happens while there are still sessions left.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"coaching-post-session-note":{id:"coaching-post-session-note",agentSlug:"town-coaching-post-session-note",version:3,name:"Client Session Follow-Up",description:"Shortly after each client session ends, drafts the note back to that client in your voice: what they said they would work on before you meet again, the date of the next session, and your rebooking or feedback link. Held in your drafts for a quick read before it goes out.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"coaching-pre-session-reminder":{id:"coaching-pre-session-reminder",agentSlug:"town-coaching-pre-session-reminder",version:3,name:"Pre-Session Form Chaser",description:"Each morning, looks a few days ahead at your booked client sessions and drafts the reminder each one needs: call link, timing, and the intake or reflection form they still owe you, with different wording for a first-time client than for someone you have worked with for a year.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"coaching-proposal-followup":{id:"coaching-proposal-followup",agentSlug:"town-coaching-proposal-followup",version:3,name:"Quiet Prospect Chaser",description:"Each weekday, finds the proposals, engagement letters, and post-discovery-call notes you sent that never got a reply, and drafts a warm follow-up for each one that names something real from your conversation instead of asking whether they saw your last email.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"cold-outreach-auto-decline":{id:"cold-outreach-auto-decline",agentSlug:"town-cold-outreach-auto-decline",version:16,name:"Decline Cold Outreach",description:"Politely declines unsolicited recruiter and sales emails by labeling cold outreach and creating an optional decline draft.",verified:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"collaborator-stub-sweep":{id:"collaborator-stub-sweep",agentSlug:"town-collaborator-stub-sweep",version:3,name:"Collaborator Stub Sweep",description:"Quickly scans recent email and calendar during onboarding to save lightweight key-contact stubs.",verified:!0,adminOnly:!0,hidden:!0,requirements:["google"],subagentSlugs:[]},"comms-content-calendar-chaser":{id:"comms-content-calendar-chaser",agentSlug:"town-comms-content-calendar-chaser",version:2,name:"Content Calendar Chaser",description:"Twice a week, reads your content calendar, finds every item sitting past its stage (draft not delivered, approval not given, asset missing), and saves a drafted nudge to whoever owes it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"comms-coverage-tracker":{id:"comms-coverage-tracker",agentSlug:"town-comms-coverage-tracker",version:2,name:"Coverage Tracker",description:"Three times a day, sweeps alerts, mail, and the web for new coverage of the brands you handle, verifies each hit, removes duplicates already in your tracker, and proposes the new rows for approval.",verified:!0,hidden:!0,requirements:["google"]},"comms-media-list-refresh":{id:"comms-media-list-refresh",agentSlug:"town-comms-media-list-refresh",version:2,name:"Media List Refresh",description:"Once a month, works through a batch of your media list, checks each reporter's recent bylines and any bounces in your mail, and proposes the corrections for reporters who changed beat, outlet, or address.",verified:!0,hidden:!0,requirements:["google"]},"comms-monthly-channel-report":{id:"comms-monthly-channel-report",agentSlug:"town-comms-monthly-channel-report",version:2,name:"Monthly Channel Report",description:"On the first of the month, builds the channel performance report for each account you cover: this month against last, the posts that actually carried it, and what you would do differently, saved as a draft document.",verified:!0,hidden:!0,requirements:["google"]},"comms-pitch-follow-up":{id:"comms-pitch-follow-up",agentSlug:"town-comms-pitch-follow-up",version:2,name:"Media Pitch Follow-Up",description:"Each weekday, finds the pitches you sent that no reporter answered, checks whether the story already ran or the angle went stale, and saves a short second email that gives the reporter a new reason to reply.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"community-lapsing-member-watch":{id:"community-lapsing-member-watch",agentSlug:"town-community-lapsing-member-watch",version:2,name:"Lapsing Member Watch",description:"Each week, compares your member roster against who actually turned up and who has been in touch, surfaces the regulars who have gone quiet, and drafts a personal re-invite for the few worth reaching out to first.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"competitive-intel":{id:"competitive-intel",agentSlug:"town-competitive-intel",version:11,name:"Competitive Intel Briefing",description:"Periodic competitive intelligence briefing. Scans the web for news, product updates, and strategic moves from competitors and adjacent players in your industry.",verified:!0,requirements:["google"]},"construction-bid-coverage-chase":{id:"construction-bid-coverage-chase",agentSlug:"town-construction-bid-coverage-chase",version:2,name:"Bid Coverage Chase",description:"Each weekday while a bid is open, Town rebuilds your coverage trade by trade from the mail: who was invited, who confirmed, who no-bid, who has gone quiet, and whose number has actually landed. Trades below your target come back flagged with the days left, and each quiet invitee gets a short follow-up drafted for you to send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"construction-change-order-watch":{id:"construction-change-order-watch",agentSlug:"town-construction-change-order-watch",version:2,name:"Unsigned Change Order Watch",description:"Twice a week, Town rebuilds every pending change from the mail - the proposals you priced, the ones deferred without a decision date, and the work already in the field on a verbal go-ahead - with the cost and time at stake and how long each has waited. Rows for your change log are proposed for your approval, and a decision-forcing note to whoever owes the signature is left drafted.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"construction-draw-chase":{id:"construction-draw-chase",agentSlug:"town-construction-draw-chase",version:2,name:"Construction Draw Chase",description:"Once a week, checks each project's draw package against what has actually arrived: the pay application, the schedule of values, conditional and unconditional lien waivers, backup invoices, and the inspection sign-off. Whatever is still missing comes back as a chase note drafted to the general contractor or sub who owes it, and a readiness checklist you can hand to the lender.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"construction-owner-project-update":{id:"construction-owner-project-update",agentSlug:"town-construction-owner-project-update",version:2,name:"Weekly Owner Project Update",description:"Every Friday morning, Town drafts the update each owner or client is expecting, built from the week that actually happened: work put in place, where the schedule stands against the milestones you set, open RFIs and submittals with their ages, pending changes and what they add, what is coming in the next two weeks, and the decisions you need from the owner with a date on each. One unsent draft per project, in the thread you already use.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"construction-rfi-submittal-clock":{id:"construction-rfi-submittal-clock",agentSlug:"town-construction-rfi-submittal-clock",version:2,name:"RFI and Submittal Clock",description:"Twice each weekday, Town rebuilds your open RFIs and submittals from the mail and puts a date on each one: what was transmitted, what came back, who is holding it now, and how far it has run against the response window in your contract. Items held by someone else come back with a drafted follow-up that names the sheet, the crew waiting, and the date. Items sitting in your own court are listed separately so you answer before the window closes.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"construction-site-meeting-actions":{id:"construction-site-meeting-actions",agentSlug:"town-construction-site-meeting-actions",version:2,name:"Site Meeting Action Log",description:"After an owner-architect-contractor or trade coordination meeting ends, Town turns the notes into the log the job actually runs on: what was decided, who owns each action, and the date it is due, with last meeting's unresolved items carried forward and aging. The log updates in your own project document, and the minutes that go out to the attendees are left drafted for you to review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"consultant-blocked-input-chaser":{id:"consultant-blocked-input-chaser",agentSlug:"town-consultant-blocked-input-chaser",version:2,name:"Blocked Input Chaser",description:"Twice a workday, Town sweeps your client threads for the data, approvals, intros, and sign-offs you asked for and never got, ages each open ask, and holds a short nudge draft in the original thread once an ask passes the waiting limit you set.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"consultant-client-status-drafts":{id:"consultant-client-status-drafts",agentSlug:"town-consultant-client-status-drafts",version:2,name:"Weekly Client Status Drafts",description:"Each Friday morning, Town reconstructs what actually moved on every active engagement from that client's threads, calendar, and trackers, and saves one short status draft per client — shipped, in progress, blocked, and what you need from them — held for your edit.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"consultant-invoice-hours-rebuild":{id:"consultant-invoice-hours-rebuild",agentSlug:"town-consultant-invoice-hours-rebuild",version:2,name:"Billable Hours Recap",description:"On the first of each month, Town rebuilds the month just closed from your calendar, threads, and tracker, finds the client work you never logged, produces an invoice-ready summary by category with the detailed log behind it, and holds the invoice email as a draft.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"consultant-post-call-commitments":{id:"consultant-post-call-commitments",agentSlug:"town-consultant-post-call-commitments",version:2,name:"Client Call Follow-Up",description:"After a client call ends, Town reads the notes or transcript, separates what you committed to from what the client committed to, saves a dated next-steps log for that engagement, and holds one recap email draft in the existing client thread for your edit.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"consultant-retainer-burn-watch":{id:"consultant-retainer-burn-watch",agentSlug:"town-consultant-retainer-burn-watch",version:2,name:"Retainer Burn Watch",description:"Every Wednesday, Town compares the hours each engagement has consumed against the hours you sold, projects where the period lands at the current pace, and names the specific requests that pushed a client outside the agreed scope — while there is still time to have the conversation.",verified:!0,hidden:!0,requirements:["google"]},"contact-relationship-mapper":{id:"contact-relationship-mapper",agentSlug:"town-contact-relationship-mapper",version:5,name:"Contact Relationship Mapper",description:"Hidden internal agent that classifies a user's contact roster as one coherent relationship map, using full contact profiles and bounded email or calendar reads only when the saved evidence is ambiguous.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"contact-research-dossier":{id:"contact-research-dossier",agentSlug:"town-contact-research-dossier",version:10,name:"Contact Research Dossier",description:"Automatically researches new contacts when an incoming email is labeled with your trigger label. Delivers a comprehensive briefing covering company overview, funding, news, LinkedIn profile, competitors, key executives, and industry trends.",verified:!0,requirements:["google"]},"content-organizer":{id:"content-organizer",agentSlug:"town-content-organizer",version:18,name:"Content Organizer",description:"Organizes uncategorized content in your Content Library into semantic collections",verified:!0,adminOnly:!0,hidden:!0,requirements:[]},"creative-client-friday-update":{id:"creative-client-friday-update",agentSlug:"town-creative-client-friday-update",version:2,name:"Friday Client Update",description:"Every active client expects a note on where their work stands, and it is the thing that slips at five o'clock on Friday. Once a week this reconstructs what actually moved on each client's work from the threads, files, and calendar behind it, then saves one drafted update per client in the thread that client already uses: what you shipped, what is sitting in review, what you are still waiting on from them, and the date that slips if they do not answer. Every one of them stays a draft.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"creative-handoff-spec-check":{id:"creative-handoff-spec-check",agentSlug:"town-creative-handoff-spec-check",version:3,name:"Creative Handoff Audit",description:"Twice a day, this looks at the creative files you sent out and rebuilds what you actually promised for that delivery from the brief and the thread: formats, sizes, color handling, bleed, variants, naming, and the date. It sends you one checklist per handoff showing what matched, what is missing, and what it could not verify, while there is still time to resend.",verified:!0,hidden:!0,requirements:["google"]},"creative-work-in-flight":{id:"creative-work-in-flight",agentSlug:"town-creative-work-in-flight",version:2,name:"Creative Work Tracker",description:"Keep one living board of every piece of creative you have in flight. Each weekday morning it re-reads the briefs, threads, and calendar behind each deliverable, moves it to the stage the evidence supports, and names who the next move belongs to, so a round that has been sitting for a week stops being invisible.",verified:!0,hidden:!0,requirements:["google"]},"creator-brand-call-terms":{id:"creator-brand-call-terms",agentSlug:"town-creator-brand-call-terms",version:2,name:"Brand Deal Terms Log",description:"Shortly after a brand or partnership call ends, pulls the terms that were actually agreed out of the notes and thread, writes them into one deal record, and holds any tracker write for your approval.",verified:!0,hidden:!0,requirements:["google"]},"creator-brand-impersonation-sweep":{id:"creator-brand-impersonation-sweep",agentSlug:"town-creator-brand-impersonation-sweep",version:2,name:"Brand Impersonation Sweep",description:"Twice a week, searches the open web for accounts, listings, and pages using your name or work without permission, screens out the ones you have already cleared, and saves an unsent takedown notice for each real find.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"creator-content-calendar-hygiene":{id:"creator-content-calendar-hygiene",agentSlug:"town-creator-content-calendar-hygiene",version:2,name:"Content Calendar Audit",description:"Every Monday, checks each dated publishing slot in the lookahead window for a started draft, a confirmed guest, a filled sponsor slot, and any promise you made about it, then reports only the slots that are not covered yet.",verified:!0,hidden:!0,requirements:["google"]},"creator-sponsor-invoice-chase":{id:"creator-sponsor-invoice-chase",agentSlug:"town-creator-sponsor-invoice-chase",version:2,name:"Sponsor Invoice Chaser",description:"Twice a week, matches the invoices you sent brands against the payments and promises in your own mail, then saves an unsent nudge for each one that has passed its terms.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"creator-sponsorship-offer-desk":{id:"creator-sponsorship-offer-desk",agentSlug:"town-creator-sponsorship-offer-desk",version:3,name:"Sponsorship Offer Spotter",description:"Sweeps your accounts three times a day for new sponsorship, collaboration, and paid-speaking offers, records what each one is actually offering, and saves an unsent reply that asks for the terms they left out.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"cs-client-promise-chaser":{id:"cs-client-promise-chaser",agentSlug:"town-cs-client-promise-chaser",version:2,name:"Client Promise Chaser",description:"The bug fix, the ETA, the credit, the security answer. Town rebuilds the list of things your company owes your customers, checks whether each one actually moved, drafts the nudge to the internal owner, and hands you the exact line to send the client back.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"cs-client-sync-recap":{id:"cs-client-sync-recap",agentSlug:"town-cs-client-sync-recap",version:2,name:"Client Sync Recap",description:"Minutes after an external client meeting ends, Town reconstructs what was actually agreed from the meeting's own notes and the account's live thread, then saves an unsent recap in that thread carrying the next steps with an owner and a date on each side, plus the items still open from the last sync, so the recap you owe is written before the next call starts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"cs-onboarding-blocker-sweep":{id:"cs-onboarding-blocker-sweep",agentSlug:"town-cs-onboarding-blocker-sweep",version:2,name:"Onboarding Blocker Sweep",description:"New accounts stall quietly: a data file nobody sent, an integration key waiting on IT, a training session never booked. Twice a week Town checks every account still in onboarding against its own plan, names the step that has not moved and who owns it, and drafts the nudge so the go-live date survives.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"cs-qbr-pack-draft":{id:"cs-qbr-pack-draft",agentSlug:"town-cs-qbr-pack-draft",version:2,name:"QBR Pack",description:"Town finds the accounts with a business review coming up and reconstructs the quarter from what actually happened: outcomes delivered, escalations opened and closed, adoption changes the client themselves described, open asks, and the plan for next quarter. You get a private draft pack per account, weeks before you would have started it.",verified:!0,hidden:!0,requirements:["google"]},"cs-quiet-account-renewal-watch":{id:"cs-quiet-account-renewal-watch",agentSlug:"town-cs-quiet-account-renewal-watch",version:2,name:"Quiet Account Renewal Watch",description:"Every Monday, Town measures the last real two-way contact on each account you cover, ranks the quiet ones by how soon they renew and how much they are worth, and saves a specific check-in draft for each so a relationship never goes cold on the way into a renewal conversation.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"daily-work-summary":{id:"daily-work-summary",agentSlug:"town-daily-work-summary",version:46,name:"Daily Work Summary",description:"A daily end-of-day email summarizing everything your assistant did for you and what still needs your attention",verified:!0,deprecated:!0,requirements:["google"],subagentSlugs:["town-daily-work-summary-researcher"]},"deal-critical-date-clock":{id:"deal-critical-date-clock",agentSlug:"town-deal-critical-date-clock",version:2,name:"Deal Critical-Date Clock",description:"Every morning, reads the purchase agreements, amendments, extensions, and escrow notices behind the properties you have under contract, and keeps one clock of the dates that cost money: due diligence expiring, financing contingency, the day the deposit goes hard, rate lock, and closing. You get told before each one, with the clause it came from and the days remaining.",verified:!0,hidden:!0,requirements:["google"]},"deal-spotter":{id:"deal-spotter",agentSlug:"town-deal-spotter",version:10,name:"Deal Spotter",description:"Scans incoming emails for sales and biz dev opportunities (inbound leads, pricing discussions, proposals, partnership interest) and logs them to a Google Sheet with next steps.",verified:!0,requirements:["google"]},"design-review-revision-list":{id:"design-review-revision-list",agentSlug:"town-design-review-revision-list",version:2,name:"Feedback Revision List",description:"After a design review, the notes are spread across three people talking over each other. This turns the transcript into a single revision list, grouped by the asset each note belongs to, separated into changes that were asked for and opinions that were floated, with anything that contradicts an earlier round or sits outside the signed brief called out. A short confirmation of what you heard is drafted for the room and held for your review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"dsci-analysis-request-queue":{id:"dsci-analysis-request-queue",agentSlug:"town-dsci-analysis-request-queue",version:2,name:"Analysis Request Queue",description:"Three times each weekday, rebuilds the open asks for numbers, pulls, and dashboard changes out of the mail they arrived in, and separates the two that cost the most time: the question you already answered somewhere the requester never looked, and the question nobody can start because a definition, a window, or a segment was never stated. It writes one scoping question per requester and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"dsci-findings-reply-chase":{id:"dsci-findings-reply-chase",agentSlug:"town-dsci-findings-reply-chase",version:2,name:"Findings Decision Chase",description:"Twice each weekday, finds the analyses you delivered that nobody has replied to, checks whether anything happened anyway, and lists the ones where a stated decision is still sitting open on the other side. It writes one unsent nudge per thread that names the decision rather than asking for a read receipt; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"dsci-followup-cut-tracker":{id:"dsci-followup-cut-tracker",agentSlug:"town-dsci-followup-cut-tracker",version:2,name:"Follow-Up Cut Tracker",description:"Once a data review or readout finishes transcribing, pulls out every follow-up the room asked for: the extra segment, the rerun with a different filter, the objection that has to be answered before anyone trusts the result. Each one is captured with who asked, the question behind it, and whether it needs data you do not already have. It writes one unsent note back to attendees listing what was asked; switch to report-only if you just want the private recap.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"dsci-metric-mismatch-watch":{id:"dsci-metric-mismatch-watch",agentSlug:"town-dsci-metric-mismatch-watch",version:2,name:"Metric Mismatch Watch",description:"Late morning and late afternoon on weekdays, rebuilds every open thread where two numbers for the same thing disagree, and keeps the part that gets lost between replies: which figures were compared, which explanations have already been ruled out, and who owes the next check. It writes one unsent reply per open mismatch asking for the one thing that would settle it; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"dsci-recurring-report-register":{id:"dsci-recurring-report-register",agentSlug:"town-dsci-recurring-report-register",version:2,name:"Recurring Report Register",description:"Every Monday and Thursday, rebuilds the reports you send on a rhythm from your own send history, works out when each one is next due, and separates the two failures nobody notices in time: the report whose inputs have not arrived yet, and the report that quietly stopped going out three cycles ago. Report-only, and it never sends a report on your behalf.",verified:!0,hidden:!0,requirements:["google"]},"ea-calendar-landmine-sweep":{id:"ea-calendar-landmine-sweep",agentSlug:"town-ea-calendar-landmine-sweep",version:2,name:"Calendar Health Audit",description:"Twice each workday, the next several business days on every calendar you manage get swept for the four things that ruin a meeting on the day: an invite the other side never accepted, a real double-booking, a meeting with no room or dial-in, and a gap too short to physically make. You get one prioritized note, and the same landmine is never reported to you twice.",verified:!0,hidden:!0,requirements:["google"]},"ea-exec-decision-roundup":{id:"ea-exec-decision-roundup",agentSlug:"town-ea-exec-decision-roundup",version:2,name:"Exec Decision Digest",description:"Each weekday morning, collect everything that is genuinely blocked on your executive: approvals, signatures, invite responses, intro yes-or-no calls, and document reviews. Each item arrives with the one line of context you need and how long it has been sitting, ranked so you can walk the list in a few minutes.",verified:!0,hidden:!0,requirements:["google"]},"ea-lapsed-standing-meetings":{id:"ea-lapsed-standing-meetings",agentSlug:"town-ea-lapsed-standing-meetings",version:3,name:"Lapsed Meeting Watch",description:"Once a week, find the standing 1:1s and check-ins that quietly stopped happening after too many cancellations, plus the meetings your executive agreed to but nobody ever booked. Each one comes back with open times and a short reschedule note saved to your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"ea-scheduling-thread-chaser":{id:"ea-scheduling-thread-chaser",agentSlug:"town-ea-scheduling-thread-chaser",version:3,name:"Scheduling Thread Chaser",description:"Three times a day, find the scheduling threads where you offered times and nobody wrote back. Each one is checked against the live calendar, stale slots are replaced with times that are still open, and a short nudge is saved to your drafts for a quick look before it goes out.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"ea-trip-logistics-checklist":{id:"ea-trip-logistics-checklist",agentSlug:"town-ea-trip-logistics-checklist",version:2,name:"Trip Readiness Audit",description:"Each weekday morning, every trip inside your planning horizon is reconciled against the confirmations already sitting in your mail. You get only what is still missing, with the vendor or counterpart chase email drafted and waiting.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"edu-committee-follow-through":{id:"edu-committee-follow-through",agentSlug:"town-edu-committee-follow-through",version:2,name:"Committee Follow-Through",description:"Once a week, Town reads the agendas, minutes, and threads from your department and committee work and pulls out only the items you personally agreed to do - the review you owe, the vote still open, the section of the report with your name on it - each with the date it is due and how late it already is.",verified:!0,hidden:!0,requirements:["google"]},"edu-extension-promise-log":{id:"edu-extension-promise-log",agentSlug:"town-edu-extension-promise-log",version:2,name:"Extension Promise Log",description:"Every weekday morning, Town reads the replies you sent students and pulls out every date you granted - the extension, the make-up assessment, the incomplete you agreed to, the accommodation you have to honor - into one dated log, and tells you which of those dates arrive today or this week. The log update waits for your approval before it is written.",verified:!0,hidden:!0,requirements:["google"]},"edu-missing-work-chase":{id:"edu-missing-work-chase",agentSlug:"town-edu-missing-work-chase",version:2,name:"Missing Work Chase",description:"Once a week, Town reads the missing-work list you keep and works out who still has outstanding work with the grading deadline approaching, who you have already contacted about it, and who you have not. Turn drafting on and it writes the outreach in your voice, one message per student, and leaves each one unsent in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"edu-recommendation-deadline-watch":{id:"edu-recommendation-deadline-watch",agentSlug:"town-edu-recommendation-deadline-watch",version:2,name:"Recommendation Deadline Watch",description:"Twice a week, Town rebuilds the list of recommendation letters you agreed to write, dates each one against the deadline the student gave you, and names what is still missing from them - the signed waiver, the resume, the program list, the submission link. Turn drafting on and it writes the request to the student and leaves it unsent in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"edu-student-meeting-recap":{id:"edu-student-meeting-recap",agentSlug:"town-edu-student-meeting-recap",version:2,name:"Student Meeting Recap",description:"Shortly after a conference, advising appointment, or student support meeting ends, Town writes the recap back to the people who were in it: what you agreed to do, what the student agreed to do, the dates attached to each, and when you will check in again. Held unsent in your drafts for a quick read.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"em-interview-loop-chase":{id:"em-interview-loop-chase",agentSlug:"town-em-interview-loop-chase",version:2,name:"Interview Loop Chase",description:"Twice each weekday, Town rebuilds the live candidates for your open roles from your own mail and calendar and keeps the ones whose next step is stuck on your side of the loop - the interview with no written feedback, the debrief nobody scheduled, the advance-or-pass call still sitting with you. Turn drafting on and it writes the nudge to whoever holds the step and leaves it unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"em-leadership-eng-update":{id:"em-leadership-eng-update",agentSlug:"town-em-leadership-eng-update",version:2,name:"Engineering Leadership Update",description:"Late each week, Town rebuilds what your teams actually shipped and what slipped from merged work, closed issues, incidents, and your own threads, adds where hiring stands, and drafts the update you owe the leadership table in your format - leading with the decisions you need from them. It is saved for you to edit, never sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"em-one-on-one-growth-record":{id:"em-one-on-one-growth-record",agentSlug:"town-em-one-on-one-growth-record",version:2,name:"One-on-One Growth Record",description:"When a one-on-one finishes transcribing, Town checks it really was a two-person sync with one of your reports, pulls out what they are working on, what they asked for, and what each of you committed to, then adds a dated entry to that person's growth record - with last time's commitments marked kept or still open. The entry waits for your approval before it is written.",verified:!0,hidden:!0,requirements:["google"]},"em-open-req-roundup":{id:"em-open-req-roundup",agentSlug:"town-em-open-req-roundup",version:2,name:"Open Req Roundup",description:"Before the weekly hiring sync, Town rebuilds each open req from your own mail, calendar, and pipeline sheet: who entered the loop, who advanced, who dropped and the reason they gave, what is booked this week, and which reqs produced no movement at all. It ends with the decisions the sync needs from you, and it stays a private read.",verified:!0,hidden:!0,requirements:["google"]},"em-service-health-watch":{id:"em-service-health-watch",agentSlug:"town-em-service-health-watch",version:2,name:"Service Health Watch",description:"Twice each weekday, Town reads the health and metric reports your services already send you, checks each number you declared against its threshold and its own recent history, and reports only the ones that breached or are sliding the wrong way - with the deploy or change that landed beside them, and what is still unresolved from the last run.",verified:!0,hidden:!0,requirements:["google"]},"email-router":{id:"email-router",agentSlug:"town-email-router",version:1,name:"Email router",description:"Evaluates your smart email trigger conditions against each incoming email and starts only the routines that match.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:["town-email-criteria-triager"]},"eng-blocked-work-chase":{id:"eng-blocked-work-chase",agentSlug:"town-eng-blocked-work-chase",version:2,name:"Blocked Work Chase",description:"Each weekday afternoon, sweeps the questions you asked and the dependencies you are waiting on across Slack threads, issue comments, and email, finds the ones that went unanswered, and drafts a follow-up that restates the ask - so your work stops sitting behind someone else's silence.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"eng-incident-followthrough":{id:"eng-incident-followthrough",agentSlug:"town-eng-incident-followthrough",version:2,name:"Postmortem Fix Ledger",description:"Once a week, reconciles the action items promised in recent incident reviews and postmortems against what has actually merged, names the fixes still open and who owns them, and drafts the nudge for each one that has gone quiet.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"eng-meeting-agreed-work":{id:"eng-meeting-agreed-work",agentSlug:"town-eng-meeting-agreed-work",version:2,name:"Meeting Commitment Log",description:"After an engineering meeting finishes transcribing, extracts only the work the room actually committed to, attaches the decision each piece of work implements, dedupes it against tracked work that already exists, and files or drafts the rest with an owner named.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"eng-review-stall-chase":{id:"eng-review-stall-chase",agentSlug:"town-eng-review-stall-chase",version:3,name:"Review Stall Chase",description:"Twice each weekday, checks the pull requests you opened and the ones assigned to you, finds the ones that have gone quiet past your own threshold, and drafts a specific, collegial nudge for each - so your code stops waiting on silence and nobody waits on you either.",verified:!0,hidden:!0,requirements:["google","github"],subagentSlugs:["town-write-in-user-voice"]},"eng-standup-update":{id:"eng-standup-update",agentSlug:"town-eng-standup-update",version:2,name:"Standup Update",description:"Early each weekday, rebuilds what you actually moved since your last workday from your commits, pull requests, issue-tracker activity, and meeting notes, then writes the three-part standup update - finished, in flight, blocked - as a private draft you can paste or read out loud.",verified:!0,hidden:!0,requirements:["google"]},"events-load-in-chase":{id:"events-load-in-chase",agentSlug:"town-events-load-in-chase",version:2,name:"Load-In Open Items",description:"Each morning, finds the events coming up on your calendar, works out what is still outstanding for each one and who owes it, and saves a drafted nudge for every person who owes you something. Nothing is sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"events-registrant-followup":{id:"events-registrant-followup",agentSlug:"town-events-registrant-followup",version:2,name:"Attendee Follow-Up",description:"Twice a day, finds the events and webinars that have finished, reads your registrant source, and saves one individualized unsent follow-up for each person on it, grounded in what that person actually did: asked a question, showed up, or registered and never appeared. Nothing is sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"events-sponsor-call-followup":{id:"events-sponsor-call-followup",agentSlug:"town-events-sponsor-call-followup",version:2,name:"Sponsor Call Follow-Up",description:"After a sponsor, venue, or vendor call ends, drafts the follow-up in your voice with what was agreed, what you promised to send, and what you are waiting on from them. Saved in the existing thread, unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"events-sponsor-wrap-report":{id:"events-sponsor-wrap-report",agentSlug:"town-events-sponsor-wrap-report",version:2,name:"Sponsor Wrap Report",description:"After an event runs, assembles one private wrap report per sponsor: what you promised them, what actually shipped, the numbers you can evidence, and the gaps that still need a real answer before you send it.",verified:!0,hidden:!0,requirements:["google"]},"exec-decision-record":{id:"exec-decision-record",agentSlug:"town-exec-decision-record",version:2,name:"Leadership Decision Log",description:"Each Friday, extracts the week's settled leadership decisions with their owner, date, rejected alternatives, and reopening condition, then proposes the append to the decision log for approval.",verified:!0,hidden:!0,requirements:["google"]},"exec-handoff-chaser":{id:"exec-handoff-chaser",agentSlug:"town-exec-handoff-chaser",version:2,name:"Delegation Chaser",description:"Twice each weekday, rebuilds the list of things the user delegated, marks what came back, and saves held nudge drafts only for the items that are genuinely overdue.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"exec-investor-update-draft":{id:"exec-investor-update-draft",agentSlug:"town-exec-investor-update-draft",version:2,name:"Monthly Investor Update",description:"Early each month, rebuilds the period from real activity, reconciles the prior update's commitments and asks, and saves one private draft in the founder's own voice without sending it.",verified:!0,hidden:!0,requirements:["google"]},"exec-partner-thread-revival":{id:"exec-partner-thread-revival",agentSlug:"town-exec-partner-thread-revival",version:2,name:"Partner Re-Engagement Drafts",description:"Each Tuesday, finds partnership, BD, and intro threads that stalled after real momentum and saves an unsent re-engagement draft carrying a concrete new reason to talk.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"exec-weekly-priority-plan":{id:"exec-weekly-priority-plan",agentSlug:"town-exec-weekly-priority-plan",version:2,name:"Week Ahead Plan",description:"Every Sunday evening, rebuilds one living plan for the week ahead from goals, calendar, projects, tasks, and open threads, carries every unfinished item forward with a stated reason, and proposes the update without overwriting the user's own edits to the plan document.",verified:!0,hidden:!0,requirements:["google"]},"finance-cash-runway-update":{id:"finance-cash-runway-update",agentSlug:"town-finance-cash-runway-update",version:2,name:"Cash & Runway Update",description:"Once a week, reads the cash, receivables, and payables exports you point it at, builds the update you owe your CEO or board with cash on hand, expected collections and payments, burn, and runway, labels every figure with its source and how fresh it is, and saves the message unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"finance-close-call-checklist":{id:"finance-close-call-checklist",agentSlug:"town-finance-close-call-checklist",version:2,name:"Close Checklist Update",description:"When a close or finance call transcript is ready, extracts the items that changed status, the owners named, and the dates agreed, proposes the exact checklist edits for your approval, and saves the asks you promised as unsent drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"finance-close-input-chaser":{id:"finance-close-input-chaser",agentSlug:"town-finance-close-input-chaser",version:2,name:"Close Input Chaser",description:"Each weekday inside your close window, checks which statements, invoices, payroll files, and approvals have actually arrived against what close needs, then saves one unsent chaser per responsible person and emails you the gap list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"finance-doc-routing-desk":{id:"finance-doc-routing-desk",agentSlug:"town-finance-doc-routing-desk",version:3,name:"Doc Routing Desk",description:"Three times each weekday, finds the finance documents that arrived by email, identifies the entity and document type, drafts the forward to accounts payable or the fund administrator with the attachment intact, and files the attachment into the matching entity folder for approval.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"finance-payment-change-guard":{id:"finance-payment-change-guard",agentSlug:"town-finance-payment-change-guard",version:2,name:"Payment Change Watch",description:"Twice each weekday, checks every request to pay against the banking details already on file, flags new accounts, changed remittance instructions, lookalike senders, and duplicate invoices, and drafts a call-back verification to the contact you already trust.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"github-reports":{id:"github-reports",agentSlug:"town-github-reports",version:28,name:"GitHub Reports",description:"Aggregates development activity from GitHub to keep you synced on what is being built, merged, and blocked",verified:!0,requirements:["github"]},"goal-tracker":{id:"goal-tracker",agentSlug:"town-goal-tracker",version:12,name:"Goal Tracker",description:"Each night, reviews the user's signals (sent emails, Slack, calendar, routine activity, memories) to understand their goals for the day, week, and month, logs the tracked goal set, and keeps a Goals page in their Knowledge wiki up to date.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"govpol-aging-inquiry-queue":{id:"govpol-aging-inquiry-queue",agentSlug:"town-govpol-aging-inquiry-queue",version:2,name:"Aging Inquiry Queue",description:"Twice each weekday, rebuilds the inquiries your office has been asked to answer and ranks them by how far past your own response window they have run. It separates the threads where you are the named recipient from the ones where you were only copied, folds a sender who has written three times about one subject into a single entry, and states what each person actually asked for in their own words. It saves one acknowledgment per thread that confirms receipt and names a next step, and leaves it unsent; switch to report-only if you just want the queue.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"govpol-comment-window-watch":{id:"govpol-comment-window-watch",agentSlug:"town-govpol-comment-window-watch",version:2,name:"Comment Window Watch",description:"Each weekday morning, reads the notices, bulletins, and committee mail your work already brings you and pulls out the dates hiding in them: comment windows about to close, hearings and markups on the calendar, testimony and filing due dates, reporting deadlines, and statutory reply dates. Every date is reported with the message that stated it and the days remaining, so a window you meant to file in does not close while the notice sits three screens down your inbox.",verified:!0,hidden:!0,requirements:["google"]},"govpol-interagency-stall-chase":{id:"govpol-interagency-stall-chase",agentSlug:"town-govpol-interagency-stall-chase",version:2,name:"Interagency Stall Chase",description:"On Tuesday and Thursday mornings, rebuilds what you have asked another office, agency, department, committee, or contractor for and reports the asks that have gone quiet past your patience threshold. It follows a document out for sign-off to whoever currently holds it, separates an ask that was referred onward from one that simply went silent, and names the dated thing each stall threatens. It writes one short nudge per stalled ask and leaves it unsent; switch to report-only if you just want the stalls.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"govpol-stakeholder-meeting-record":{id:"govpol-stakeholder-meeting-record",agentSlug:"town-govpol-stakeholder-meeting-record",version:2,name:"Stakeholder Meeting Record",description:"About an hour after a meeting ends, works out whether it was a stakeholder, constituent, or interagency conversation, and if it was, writes down the part that gets lost: who was in it, what they asked for in their own words, what your office committed to, what they committed to, and the date attached to each. It saves one unsent recap for the participants covering only what was agreed; switch to record-only if you just want the record. It records requests and commitments, never anyone's views, arguments, or affiliations.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"govpol-weekly-issue-update":{id:"govpol-weekly-issue-update",agentSlug:"town-govpol-weekly-issue-update",version:2,name:"Weekly Issue Update",description:"Every Thursday afternoon, drafts the update you owe upward, built from what actually happened rather than what you remember on the way to writing it: the threads that moved on each issue you carry, the dates that landed or are about to, the requests still sitting with another office, and the meetings you held and what they committed each side to. It writes the update with a source behind every line and leaves it unsent for you to correct.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"growth-call-recap-draft":{id:"growth-call-recap-draft",agentSlug:"town-growth-call-recap-draft",version:2,name:"Agency Call Follow-Up",description:"Shortly after an external agency, vendor, partner, or influencer call ends, drafts a recap in the existing thread that records what each side agreed to and by when, and leaves it unsent for review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"growth-channel-pacing-watch":{id:"growth-channel-pacing-watch",agentSlug:"town-growth-channel-pacing-watch",version:3,name:"Channel Pacing Watch",description:"Each Wednesday, compares spend to date against the budget for every channel you track, and flags the ones running hot or cold while there is still month left to move money.",verified:!0,hidden:!0,requirements:["google"]},"growth-content-angle-brief":{id:"growth-content-angle-brief",agentSlug:"town-growth-content-angle-brief",version:3,name:"Customer-Signal Content Ideas",description:"Each Thursday, mines your recent customer call notes, marketing documents, and campaign trends into a ranked brief of content angles, each with a format, a hook, an audience, and the source it came from, skipping anything you already published.",verified:!0,hidden:!0,requirements:["google"]},"growth-launch-asset-chaser":{id:"growth-launch-asset-chaser",agentSlug:"town-growth-launch-asset-chaser",version:2,name:"Launch Asset Chaser",description:"Twice each weekday, reads the launch plan, works out which deliverables other people still owe against the launch date, and drafts a nudge for each one that has gone quiet.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"growth-leadership-update-draft":{id:"growth-leadership-update-draft",agentSlug:"town-growth-leadership-update-draft",version:3,name:"Weekly Marketing Update",description:"Every Monday morning, assembles last week's marketing numbers from the reporting sources you point it at, writes the reasoning behind each movement, and saves a private draft for you to review and send yourself.",verified:!0,hidden:!0,requirements:["google"]},"guest-briefing":{id:"guest-briefing",agentSlug:"town-guest-briefing",version:4,name:"Guest Briefing",description:"Prepares an attendee-safe briefing for the guests of a meeting you organize, from the meeting's own shared details. Nothing sends without your confirmation.",verified:!0,requirements:[],subagentSlugs:["town-guest-brief-writer"]},"guest-doc-chat":{id:"guest-doc-chat",agentSlug:"town-guest-doc-chat",version:1,name:"Guest Document Chat",description:"Answers a link-share guest's questions about exactly one shared document. Reads that document through a secret-scoped read and nothing else; it cannot edit the document and cannot reach any other data.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"guest-onboarding":{id:"guest-onboarding",agentSlug:"town-guest-onboarding",version:3,name:"Guest Onboarding Guide",description:"Helps a phone-verified prospective user create and personalize their Townie and understand connections over text. It has no tools, integrations, memory, or user context.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"hosp-booking-inquiry-chase":{id:"hosp-booking-inquiry-chase",agentSlug:"town-hosp-booking-inquiry-chase",version:2,name:"Booking Inquiry Chase",description:"Twice a day, every day, rebuilds the booking and reservation inquiries still open in your mail and splits them two ways: the guest or client waiting on an answer from you, and the quote or held date nobody has come back on. It writes one reply per thread and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hosp-deposit-cutoff-register":{id:"hosp-deposit-cutoff-register",agentSlug:"town-hosp-deposit-cutoff-register",version:2,name:"Deposit Cutoff Register",description:"Each morning, reconciles the dated terms buried in your confirmations, contracts, and invoices into one private register: deposits due, courtesy holds expiring, room-block and seat cutoffs, final payments, and the last day to cancel without a penalty. Alerts at the lead time you set, and drafts a reminder for what the guest owes on each booking.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hosp-planning-call-recap":{id:"hosp-planning-call-recap",agentSlug:"town-hosp-planning-call-recap",version:2,name:"Planning Call Recap",description:"About an hour after a call with a guest or client ends, works out whether it was a planning conversation about a stay, trip, or booking, then pulls out the dates, party, spaces, and must-haves that were actually agreed and saves one unsent recap in the existing thread. Nothing is quoted, confirmed, or sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hosp-special-request-watch":{id:"hosp-special-request-watch",agentSlug:"town-hosp-special-request-watch",version:2,name:"Special Request Watch",description:"Each morning, reads ahead to the arrivals and departures inside your window, rebuilds every specific thing you told a guest or client you would arrange, and keeps only the ones no one has confirmed in writing. It writes one internal chase per person responsible and leaves it unsent; switch to report-only if you just want the unconfirmed list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hosp-weekly-service-update":{id:"hosp-weekly-service-update",agentSlug:"town-hosp-weekly-service-update",version:2,name:"Weekly Service Update",description:"Every Thursday morning, rebuilds the week ahead from your own mail and calendar: who is arriving, what is still unconfirmed, which dates and payments land, how the week's guest problems were closed, and the decisions you need from whoever you report to. The whole update is left drafted to the people you name, unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hr-compliance-deadline-watch":{id:"hr-compliance-deadline-watch",agentSlug:"town-hr-compliance-deadline-watch",version:2,name:"Compliance Deadline Watch",description:"Each weekday morning, rebuilds the running clock on every leave notice, return-to-work date, work-authorization reverification, accommodation follow-up, and training deadline you track, ranks them by days remaining, and saves unsent chasers for whoever owes the missing paperwork.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hr-investigation-notes":{id:"hr-investigation-notes",agentSlug:"town-hr-investigation-notes",version:2,name:"Investigation Case Notes",description:"Shortly after a fact-finding, employee-relations, or corrective-action conversation ends, turns the recording or your own notes into a dated, structured case note in your format, with who was present, what was stated, what was agreed, and what remains open, saved privately to the case file.",verified:!0,hidden:!0,requirements:["google"]},"hr-lifecycle-email-drafter":{id:"hr-lifecycle-email-drafter",agentSlug:"town-hr-lifecycle-email-drafter",version:2,name:"Lifecycle Email Drafts",description:"Each weekday it looks ahead across your roster for the people events landing soon, rebuilds each message from the template you actually used last time, fills in that person's real dates and details, and saves every one unsent for you to send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"hr-people-case-ledger":{id:"hr-people-case-ledger",agentSlug:"town-hr-people-case-ledger",version:2,name:"People Case Ledger",description:"Twice each weekday, sweeps new mail and documents for employee-relations, leave, accommodation, workers' comp, and pay-correction activity, updates one living case ledger with what changed and what each case is waiting on, and emails you only the cases that need a decision today.",verified:!0,hidden:!0,requirements:["google"]},"hr-people-leadership-update":{id:"hr-people-leadership-update",agentSlug:"town-hr-people-leadership-update",version:2,name:"Weekly People Update",description:"Late each week, reconstructs what actually moved across hiring starts, exits, open cases, compliance dates, and people programs, matches the format of your last update, and saves a private draft with the numbers you still need to confirm called out.",verified:!0,hidden:!0,requirements:["google"]},"inbox-voice-prep":{id:"inbox-voice-prep",agentSlug:"town-inbox-voice-prep",version:1,name:"Inbox Voice Prep",description:"Pre-reads your latest unread emails into the voice inbox queue twice daily, so a 'Talk through your inbox' session can open with a spoken agenda.",verified:!0,adminOnly:!0,hidden:!0,requirements:[]},"inhouse-recruiting-interview-prep":{id:"inhouse-recruiting-interview-prep",agentSlug:"town-inhouse-recruiting-interview-prep",version:2,name:"Interview Prep Drafts",description:"When an interview lands on your calendar or moves, drafts the candidate's prep email in their thread: when and where, who is on the panel, and what to expect. A rescheduled interview gets a short update draft instead. Nothing reaches a candidate until you press send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"inhouse-recruiting-pipeline-answer":{id:"inhouse-recruiting-pipeline-answer",agentSlug:"town-inhouse-recruiting-pipeline-answer",version:2,name:"Pipeline Answer",description:"When someone asks where a role stands, start a run with the role and get the answer from live reads: candidates by stage, time in stage, pass-through, and who is carrying interview hours this week against the four weeks before. The answer comes to you alone, and nothing is written.",verified:!0,hidden:!0,requirements:["google"]},"inhouse-recruiting-role-opener":{id:"inhouse-recruiting-role-opener",agentSlug:"town-inhouse-recruiting-role-opener",version:2,name:"Role Opener",description:"Record the intake for a new role in Town and get the job description drafted in your company's voice, with comparable postings read for framing. The req then opens in your record. Ashby and Notion changes, and any web address its own search did not find, wait for your approval; on a Google Sheet only you can access, it writes the row directly and lists it in the report.",verified:!0,hidden:!0,requirements:["google"]},"inhouse-recruiting-stall-chase":{id:"inhouse-recruiting-stall-chase",agentSlug:"town-inhouse-recruiting-stall-chase",version:2,name:"Hiring Process Chase",description:"Every weekday morning, finds each step your own side owes on your open roles: scorecards not submitted, debriefs not booked, interview invites not accepted, availability requests not answered, and candidates waiting on a decision. It saves one unsent nudge per late step to the colleague who holds it and sends you one report.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"invite-credits-recommender":{id:"invite-credits-recommender",agentSlug:"town-invite-credits-recommender",version:6,name:"Sharing Recommender",description:"Reviews researched people contacts and recommends people to invite to Town.",verified:!0,adminOnly:!0,requirements:["google"]},"invite-story-writer":{id:"invite-story-writer",agentSlug:"town-invite-story-writer",version:6,name:"Invite Story Writer",description:"Writes a short relationship story, personalized invite email draft, and whimsical relationship-map image for the user to review before sending an invite.",verified:!0,adminOnly:!0,requirements:["google"]},"invoice-expense-logger":{id:"invoice-expense-logger",agentSlug:"town-invoice-expense-logger",version:12,name:"Invoice & Expense Logger",description:"Detects invoices, receipts, and orders from incoming emails. Extracts vendor, amount, date, and expense type, logs them to a Google Sheet, and optionally creates a draft email to forward to your expense tracking service.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"itsec-access-review-pack":{id:"itsec-access-review-pack",agentSlug:"town-itsec-access-review-pack",version:2,name:"Access Review Pack",description:"On the 2nd of each month, pulls your latest access exports together, reconciles them against the roster and last month's review, and builds the pack: who has what, which of it is privileged, what changed, and which lines a human still has to decide. Writes back to your review sheet only with your approval.",verified:!0,hidden:!0,requirements:["google"]},"itsec-alert-anomaly-escalation":{id:"itsec-alert-anomaly-escalation",agentSlug:"town-itsec-alert-anomaly-escalation",version:2,name:"Alert Anomaly Triage",description:"Three times a day, reads the security, identity, and system alerts that landed since the last run and reconciles each one against what should have caused it: an approved deploy, a maintenance window, a new hire's first login, your own travel. Anything nothing explains gets escalated to you with the evidence trail. Everything else stays quiet.",verified:!0,hidden:!0,requirements:["google"]},"itsec-incident-postmortem-draft":{id:"itsec-incident-postmortem-draft",agentSlug:"town-itsec-incident-postmortem-draft",version:2,name:"Incident Postmortem Draft",description:"When an incident review finishes recording, reconstructs the incident's own trail — the alert, the channel, the threads, the calendar — into a postmortem draft: timeline with real timestamps, impact, contributing factors, and remediation items with named owners. Held as a private document for you to correct before anyone else reads it.",verified:!0,hidden:!0,requirements:["google"]},"itsec-offboarding-access-closure":{id:"itsec-offboarding-access-closure",agentSlug:"town-itsec-offboarding-access-closure",version:2,name:"Offboarding Access Ledger",description:"Every Monday, finds the people who left recently, rebuilds what each of them still has open across your systems, and turns the leftovers into one closure list with a named owner per item. Where an owner has to act, the nudge is written for you and left unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"itsec-security-questionnaire-drafts":{id:"itsec-security-questionnaire-drafts",agentSlug:"town-itsec-security-questionnaire-drafts",version:2,name:"Security Questionnaire Drafts",description:"Three times each weekday, picks up new security review requests and questionnaires, answers each question from your own policies, prior completed reviews, and audit reports, and leaves the response in your drafts. Anything your documents do not actually answer is left blank and listed for you, never invented.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"jobseek-application-nudge":{id:"jobseek-application-nudge",agentSlug:"town-jobseek-application-nudge",version:2,name:"No-Reply Application Chaser",description:"Each weekday morning, rebuilds the applications you submitted from your own confirmation mail, works out which ones have crossed your follow-up window with no human reply, and drafts one short nudge to a contact you actually have. One nudge per application, never a second, and nothing is sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"jobseek-hiring-deadline-watch":{id:"jobseek-hiring-deadline-watch",agentSlug:"town-jobseek-hiring-deadline-watch",version:2,name:"Hiring Deadline Watch",description:"Each weekday morning, reads the dates other people put on your search - the take-home due date, the slot you have to pick by Friday, the transcript someone asked for, the offer that expires in two weeks - and gives you one dated list with what you still owe against each one. Report only, nothing is written or sent.",verified:!0,hidden:!0,requirements:["google"]},"jobseek-interview-thank-you":{id:"jobseek-interview-thank-you",agentSlug:"town-jobseek-interview-thank-you",version:2,name:"Same-Day Thank-You Notes",description:"About an hour after an interview on your calendar ends, the invite, the thread it came from, and any recording you kept are read, and one thank-you note is drafted to each person who was actually in the room - specific about what was discussed rather than a template. Nothing is sent, and a calendar event that is not a hiring conversation is skipped in silence.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"jobseek-live-search-board":{id:"jobseek-live-search-board",agentSlug:"town-jobseek-live-search-board",version:2,name:"Still in the Running",description:"Twice a week, rebuilds the one view of the processes where a real person is actually talking to you: what stage each one is at, which ones need you this week, and which have gone quiet. Split by search, so an internship hunt and a full-time hunt stay separate, capped so it stays readable at thirty applications, and once you accept an offer, the next run names every other process you owe a withdrawal.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"jobseek-network-followthrough":{id:"jobseek-network-followthrough",agentSlug:"town-jobseek-network-followthrough",version:2,name:"Networking Follow-Through",description:"Twice each weekday, finds the relationships your search is leaking: the referral or intro you asked for and never heard back on, the offer of help you never took up, and the thing you promised to send after a coffee chat. Each one comes back with a short drafted reply, unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"knowledge-suggestions-onboarding":{id:"knowledge-suggestions-onboarding",agentSlug:"town-knowledge-suggestions-onboarding",version:1,name:"Knowledge Suggestions Onboarding",description:"Builds a new user's FIRST Suggestions rail during onboarding: a fast, scoped, snippets-only pass over the profile and inbox before the wiki, goals, and projects exist. Saves the same digest row the full engine later replaces.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"knowledge-suggestions-v3":{id:"knowledge-suggestions-v3",agentSlug:"town-knowledge-suggestions-v3",version:49,name:"Knowledge Suggestions V3",description:"Builds the Suggestions V3 digest: project groups with dated headlines and their best tasks, plus a ranked routine shortlist, pulled fresh every run and refreshed intraday while the user is active. Saves to the home-page rail.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"knowledge-suggestions":{id:"knowledge-suggestions",agentSlug:"town-knowledge-suggestions",version:9,name:"Knowledge Suggestions",description:"Each night, looks at who you are and how you work to propose 3-4 persona-level routines spanning all of Town, plus a few precise tasks/routines vetted against your recent email/calendar/Slack activity, and saves them to a home-page widget.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"knowledge-welcome":{id:"knowledge-welcome",agentSlug:"town-knowledge-welcome",version:4,name:"Knowledge Welcome",description:"After the Knowledge wiki is built and the goals, projects, and suggestions routines have run, emails the user a short welcome that their Knowledge is ready, with a brief summary of their wiki, goals, active projects, and a few of the generated suggestions.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"legal-closing-document-routing":{id:"legal-closing-document-routing",agentSlug:"town-legal-closing-document-routing",version:3,name:"Closing Document Logger",description:"Three times each weekday, sweeps for executed agreements, wire instructions, consents, and certificates that landed since the last pass, labels them, records them against the right matter in your tracker for approval, and drafts the routing or confirmation reply for you to send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"legal-deadline-register":{id:"legal-deadline-register",agentSlug:"town-legal-deadline-register",version:3,name:"Legal Deadline Register",description:"Each weekday, reconciles your compliance calendar, court and regulator correspondence, and matter calendar into one private register of live filing, response, and attestation deadlines, with the owner and days remaining beside each one.",verified:!0,hidden:!0,requirements:["google"]},"legal-leadership-update":{id:"legal-leadership-update",agentSlug:"town-legal-leadership-update",version:2,name:"Matter & Risk Update",description:"On your cadence, reconstructs the period from your matter trackers, calendar, and sent mail into the update your executives or board expect: what moved, what is due, what is escalating, and what needs a decision, saved as a draft you edit and send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"legal-negotiation-open-points":{id:"legal-negotiation-open-points",agentSlug:"town-legal-negotiation-open-points",version:2,name:"Negotiation Open Points",description:"After a call with counterparty counsel, a regulator, or a business owner, records which points closed, which stayed open, and who holds the next turn, submits them to your matter log for approval, and saves the confirming email unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"legal-renewal-notice-window":{id:"legal-renewal-notice-window",agentSlug:"town-legal-renewal-notice-window",version:2,name:"Renewal Notice Watch",description:"Each Monday, reads the executed agreements and counterparty correspondence you point it at, works backward from every renewal or expiry date to the last day notice can still be given, and keeps one private register of which windows are open, closing, or already shut.",verified:!0,hidden:!0,requirements:["google"]},"level-up":{id:"level-up",agentSlug:"town-level-up",version:11,name:"Level Up",description:"Each morning, reviews how the Townie worked for the user the previous day and proposes ranked cards, each one change that would make the Townie better for them. Read only; the For You tab shows the cards in sections.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"logistics-delivery-proof-register":{id:"logistics-delivery-proof-register",agentSlug:"town-logistics-delivery-proof-register",version:2,name:"Delivery Proof Register",description:"Each weekday afternoon, Town reconciles what was delivered against the proof that came back for it, keeps one running register of every delivery and its paperwork state, and reports the deliveries whose signed proof is still missing past your window. Proof that came back with a shortage, damage, or refusal noted on it is separated out, because that is a claim rather than a clean delivery. Town writes one unsent chase per carrier; switch to report-only if you just want the outstanding list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"logistics-dock-appointment-chase":{id:"logistics-dock-appointment-chase",agentSlug:"town-logistics-dock-appointment-chase",version:2,name:"Dock Appointment Chase",description:"Mid-morning and mid-afternoon on weekdays, Town checks every delivery you have coming against the receiving slot it needs: the ones with no appointment confirmed inside your lead time, the confirmed slots a site or carrier has since moved, and the scheduling requests sitting unanswered in your own mail. Town writes one unsent booking or confirmation ask per site; switch to report-only if you just want the gaps.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"logistics-freight-review-actions":{id:"logistics-freight-review-actions",agentSlug:"town-logistics-freight-review-actions",version:2,name:"Freight Review Actions",description:"When a carrier or customer operations review finishes transcribing, Town keeps only the shipments that were actually named on the call, the fix each side accepted for them with an owner and a date, and any standing delivery rule a site or account stated. A short confirmation is saved unsent for the people who were on the call. Rates, accessorial charges, and claim amounts are flagged for your sign-off, never confirmed back.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"logistics-shipment-exception-watch":{id:"logistics-shipment-exception-watch",agentSlug:"town-logistics-shipment-exception-watch",version:2,name:"Shipment Exception Watch",description:"Twice each weekday, Town rebuilds the shipments still in motion from carrier notices, tracking mail, and the order threads they sit in, then keeps only the ones that missed a promised delivery date, are sitting held or refused, or arrived short or damaged. Each one is tied to the order and the account it touches. Town saves one unsent heads-up per affected customer; switch to report-only if you just want the exceptions.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"logistics-weekly-freight-update":{id:"logistics-weekly-freight-update",agentSlug:"town-logistics-weekly-freight-update",version:2,name:"Weekly Freight Update",description:"Every Friday afternoon, Town assembles the week's shipping record from carrier and customer mail: what delivered against what was promised, the exceptions and the reason each carrier gave, the paperwork still outstanding, and what moves next week. It writes the update to the group you name and leaves it unsent, then tells you privately what the update does not cover.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"loose-ends-sweep":{id:"loose-ends-sweep",agentSlug:"town-loose-ends-sweep",version:22,name:"Loose-Ends Sweep",description:"Late each weekday, sweeps your mail and Slack for every open loop you personally owe and sends one private list in two parts: what genuinely cannot wait tonight, then the replies, action items, and promises still open in your name. Only what you owe, never what others owe you. It reads and reports; it never drafts, replies, or acts.",verified:!0,requirements:["google"]},"media-booking-readiness-sweep":{id:"media-booking-readiness-sweep",agentSlug:"town-media-booking-readiness-sweep",version:2,name:"Booking Readiness Sweep",description:"First thing and again late in the day on weekdays, checks every interview and recording booked inside your horizon and names what is still missing on each one: a time the other person actually confirmed, a working link or an address, permission to record, the topics they asked for, and the bio, headshot, or release you need back from them. Town saves one unsent note per booking that asks only for the gaps; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"media-embargo-deadline-clock":{id:"media-embargo-deadline-clock",agentSlug:"town-media-embargo-deadline-clock",version:2,name:"Embargo & Deadline Clock",description:"Every weekday morning, rebuilds every dated commitment your work is carrying and puts them on one clock: copy deadlines, embargo lift times with their exact hour and zone, publish and air dates, newsletter sends, and booked recording slots. Each date says where it came from and whether the other side ever confirmed it, and the ones whose inputs are still missing are marked at risk. Reports only, and changes nothing.",verified:!0,hidden:!0,requirements:["google"]},"media-interview-promise-log":{id:"media-interview-promise-log",agentSlug:"town-media-interview-promise-log",version:2,name:"Interview Promise Log",description:"Shortly after an interview or recording ends, captures the housekeeping the conversation created and nothing else: what you promised the person, what they promised you, and the ground rules they stated in their own words. It records no quotes and writes no part of your piece. Town saves one short follow-up in the existing thread, unsent, covering only what you owe them; switch to log-only if you just want the commitments recorded.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"media-post-publish-followthrough":{id:"media-post-publish-followthrough",agentSlug:"town-media-post-publish-followthrough",version:2,name:"Post-Publish Follow-Through",description:"Work goes live and the tail of it comes due. Once each weekday afternoon, Town finds the pieces and episodes that published in your recent window and rebuilds what is still owed on each one: the link you promised a source, the thank-you and assets a guest is waiting on, the transcript you said you would send, and any correction or credit request sitting unanswered in your mail. Correction requests are surfaced with the disputed line and never answered on your behalf.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"media-unanswered-ask-chase":{id:"media-unanswered-ask-chase",agentSlug:"town-media-unanswered-ask-chase",version:2,name:"Unanswered Ask Chase",description:"Twice each weekday, rebuilds the asks you sent and keeps only the ones a person never actually answered: the interview request that got no reply, the records request sitting past its response window, the pitch an editor never came back on, the guest who never confirmed. Each one carries the last thing they said, how long it has been, and the deadline or run date it blocks. Town saves one short follow-up per thread and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"meeting-briefing":{id:"meeting-briefing",agentSlug:"town-meeting-briefing",version:22,name:"Meeting Briefing",description:"Prepares internal or external meeting briefings, emails them to you, saves each one in Town, and can optionally add a private shadow calendar copy.",verified:!0,requirements:["google"]},"meeting-notes-recap":{id:"meeting-notes-recap",agentSlug:"town-meeting-notes-recap",version:1,name:"Meeting Notes Hand-Off",description:"After post-meeting notes are linked to a calendar meeting — from a Town recording, Granola, Gemini, or another source — Town separates what was actually agreed from what was merely discussed, checks it against the work already tracked for each owner, and proposes only the genuinely new items as Town tasks or Linear issues. Anything you personally promised comes back as an unsent draft, internal Slack routing waits for your approval, and one private handoff summary records the whole pass.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"meeting-review":{id:"meeting-review",agentSlug:"town-meeting-review",version:12,name:"Meeting Review",description:"Transforms long voice recordings into structured meeting notes with one-click follow-up actions, with the source recording linked for full-transcript access.",adminOnly:!0,requirements:["google"]},"memory-reflection-engine":{id:"memory-reflection-engine",agentSlug:"town-memory-reflection-engine",version:21,name:"Memory Reflection Engine",description:"Reflects on recent personal assistant conversations to extract lasting preferences, relationships, and patterns into memories.",verified:!0,adminOnly:!0,requirements:["google"],subagentSlugs:["town-research-person"]},"memory-synthesis":{id:"memory-synthesis",agentSlug:"town-memory-synthesis",version:11,name:"Memory Synthesis",description:"Consolidates the user's stored memories the way sleep consolidates a brain's: expires the noisy and stale, merges duplicates and fragments into clearer memories, enriches and classifies them, and keeps the user profile (user.md) consistent with memories — lifting durable long-term characteristics into the profile and removing the duplication from memories.",verified:!0,adminOnly:!0,requirements:[]},"ml-dependency-change-watch":{id:"ml-dependency-change-watch",agentSlug:"town-ml-dependency-change-watch",version:2,name:"Dependency Change Watch",description:"Each weekday, check the providers and libraries your systems actually depend on for deprecations, breaking changes, and limit changes, and report only what touches your stack, what it breaks, and by when. You find out from the notice, not from a failing job.",verified:!0,hidden:!0,requirements:["google"]},"ml-design-decision-log":{id:"ml-design-decision-log",agentSlug:"town-ml-design-decision-log",version:3,name:"Design Decision Log",description:"After a design review or architecture call, capture the decision, the options that lost, and the reason each one lost, then append it to your running design doc or decision log for approval. Six weeks later nobody has to reconstruct why you picked that serving stack, that eval metric, or that chunking strategy.",verified:!0,hidden:!0,requirements:["google"]},"ml-interview-pipeline-tracker":{id:"ml-interview-pipeline-tracker",agentSlug:"town-ml-interview-pipeline-tracker",version:2,name:"Interview Pipeline Tracker",description:"Once a week, rebuild every live conversation from your own mail and calendar: which stage each one is at, who owes the next reply, and which has gone quiet long enough to need a nudge. A search that runs in parallel with a hard week stops depending on your memory.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"ml-overdue-task-reset":{id:"ml-overdue-task-reset",agentSlug:"town-ml-overdue-task-reset",version:3,name:"Overdue Task Sweep",description:"Every weekday morning, read the overdue pile in your tracker, weigh it against the hours your calendar actually leaves you, and propose the small handful worth pulling into today. The rest stays where it is, and every date change waits for your approval.",verified:!0,hidden:!0,requirements:["google"]},"ml-weekly-work-update":{id:"ml-weekly-work-update",agentSlug:"town-ml-weekly-work-update",version:3,name:"Weekly Work Update",description:"Late each week, reconstruct what you actually shipped from merged pull requests, closed issues, and the documents you wrote, then draft the update you owe your lead in your format. The half hour you normally spend remembering your own week is already done.",verified:!0,hidden:!0,requirements:["google"]},"morning-briefing":{id:"morning-briefing",agentSlug:"town-morning-briefing",version:82,name:"Morning Briefing",description:"A daily email with your schedule, urgent items that need attention, and updates on topics you care about",verified:!0,requirements:["google"],subagentSlugs:["town-briefing-writer"]},"new-user-research":{id:"new-user-research",agentSlug:"town-new-user-research",version:11,name:"New User Research",description:"Monitors a Slack channel for new user signups and posts research summaries with professional background, company info, and key context.",verified:!0,adminOnly:!0,hidden:!0,requirements:["workspace_slack"]},"newsletter-digest":{id:"newsletter-digest",agentSlug:"town-newsletter-digest",version:14,name:"Newsletter Digest",description:'Compiles a weekly digest of your labeled newsletters with concise summaries and links to originals. Requires Auto-inbox enabled with a "newsletters" label so incoming newsletters get labeled for the digest.',verified:!0,requirements:["google"]},"nonprofit-advancement-board-update":{id:"nonprofit-advancement-board-update",agentSlug:"town-nonprofit-advancement-board-update",version:2,name:"Weekly Advancement Update",description:"Every week, rebuilds the development picture from your own gift notices, grant mail, and donor meetings, then drafts the update your board and committee expect: raised against goal, what closed, what is at risk, and the asks in front of you, with every number carrying its source.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"nonprofit-donor-ask-followups":{id:"nonprofit-donor-ask-followups",agentSlug:"town-nonprofit-donor-ask-followups",version:2,name:"Donor Ask Watch",description:"Every weekday morning, reviews the solicitations, stewardship notes, and funder threads you sent that nobody answered, ranks them by what is actually at stake, and hands you a short list of who to nudge today with the evidence behind each one.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"nonprofit-donor-contact-report":{id:"nonprofit-donor-contact-report",agentSlug:"town-nonprofit-donor-contact-report",version:2,name:"Donor Contact Report",description:"After a donor or funder visit, turns what was actually said into the contact report your donor record needs, with the interests, capacity signals, objections, and the next move you agreed to, plus the personal note back to them, both waiting for your review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"nonprofit-gift-acknowledgments":{id:"nonprofit-gift-acknowledgments",agentSlug:"town-nonprofit-gift-acknowledgments",version:2,name:"Gift Acknowledgment Drafts",description:"Three times a day, picks up the gifts that landed since the last sweep, from platform receipts to donor-advised fund letters to a check someone emailed about, and writes the thank-you in your voice with the right amount, designation, and a real reason it mattered, saved unsent for you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"nonprofit-pledge-fulfillment-chase":{id:"nonprofit-pledge-fulfillment-chase",agentSlug:"town-nonprofit-pledge-fulfillment-chase",version:2,name:"Pledge Fulfillment Chase",description:"Every week, compares what people promised against what actually arrived, then drafts the reminder in a stewardship voice, because a donor who forgot is not a customer who owes you, and a trustee commitment or matching gift left unclaimed is money already raised.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"onboarding-recommender":{id:"onboarding-recommender",agentSlug:"town-onboarding-recommender",version:2,name:"Onboarding Routine Recommender",description:"Classifies a ready onboarding profile and saves a small set of eligible stock-routine recommendations.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"one-on-one-evidence-notes":{id:"one-on-one-evidence-notes",agentSlug:"town-one-on-one-evidence-notes",version:3,name:"Direct-Report Feedback Prep",description:"Once a week, reads a bounded window of the mail, optional Slack, and notes you already had access to, and turns the work you can actually see into private, source-linked points to reinforce and points to develop for each person you manage.",verified:!0,hidden:!1,requirements:["google"]},"one-shot-work-finder":{id:"one-shot-work-finder",agentSlug:"town-one-shot-work-finder",version:2,name:"One-Shot Work Finder",description:"At 6 AM and noon, finds concrete jobs in your connected sources and prepares complete execution prompts as One-shot suggestions in Messages.",verified:!0,requirements:[],subagentSlugs:[]},"ops-blocked-handoff-chase":{id:"ops-blocked-handoff-chase",agentSlug:"town-ops-blocked-handoff-chase",version:2,name:"Blocked Handoff Chaser",description:"Twice a weekday, Town finds the requests you are blocked on that have gone quiet - the redline sitting in Legal, the PO waiting on Finance, the access request nobody picked up - and tells you who is holding each one and what slips downstream. Turn drafting on and it writes the deadline-specific nudge and leaves it in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"ops-missing-report-chase":{id:"ops-missing-report-chase",agentSlug:"town-ops-missing-report-chase",version:2,name:"Missing Report Chaser",description:"Every weekday morning, Town checks the recurring reports, checklists, and numbers your team owes you against who actually sent them, and tells you exactly who is missing and how late they are. Turn drafting on and it writes the individual reminder and leaves it in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"ops-recurring-issue-log":{id:"ops-recurring-issue-log",agentSlug:"town-ops-recurring-issue-log",version:2,name:"Recurring Issue Log",description:"At the end of each weekday, Town turns the operational problems that landed in your mail - the breakdowns, outages, damage reports, vendor failures, and site complaints - into structured rows in one register, then tells you which site, vendor, or fault has now happened enough times to be a pattern rather than bad luck.",verified:!0,hidden:!0,requirements:["google"]},"ops-review-action-ledger":{id:"ops-review-action-ledger",agentSlug:"town-ops-review-action-ledger",version:2,name:"Review Action Ledger",description:"When your operating review finishes transcribing, Town first goes and checks what actually happened to last cycle's actions - looking for real evidence in your tracker, documents, and mail, not just what the room claimed - then turns this cycle's commitments into actions with one named owner and one stated date.",verified:!0,hidden:!0,requirements:["google"]},"ops-weekly-operating-update":{id:"ops-weekly-operating-update",agentSlug:"town-ops-weekly-operating-update",version:2,name:"Weekly Operating Update",description:"Every Friday afternoon, get the weekly operating update drafted from your own metric sources - headline numbers, what moved week over week and why, open actions with their owners, and every stale or missing input named - saved as a private draft for your edit before Monday.",verified:!0,hidden:!0,requirements:["google"]},"pe-deal-file-log":{id:"pe-deal-file-log",agentSlug:"town-pe-deal-file-log",version:2,name:"Deal File Log",description:"Twice a day, Town matches each new counterparty thread to the deal it belongs to and appends what actually moved — stage, decisions, materials received, who owes what next — to that deal's file, and asks you when the match is ambiguous instead of guessing. Your deal tracker row updates only with your approval.",verified:!0,hidden:!0,requirements:["google"]},"pe-deal-materials-triage":{id:"pe-deal-materials-triage",agentSlug:"town-pe-deal-materials-triage",version:3,name:"Buy-Box Deal Screen",description:"Three times a day, Town opens the teasers, CIMs, and management decks that landed, pulls the revenue, EBITDA, margin, growth, and asking price straight out of the file, and screens each one against your buy box — so you decide what deserves a real read from the numbers, not the banker's cover note.",verified:!0,hidden:!0,requirements:["google"]},"pe-management-meeting-commitments":{id:"pe-management-meeting-commitments",agentSlug:"town-pe-management-meeting-commitments",version:2,name:"Deal Commitments Log",description:"When a deal call finishes transcribing, Town writes down what was actually said out loud: the figures management gave with their exact wording, every spoken answer that disagrees with the diligence record already gathered, and both sides' open items with only the dates someone stated. The confirmation email back to the counterparty is drafted and held for you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pe-partner-pipeline-update":{id:"pe-partner-pipeline-update",agentSlug:"town-pe-partner-pipeline-update",version:2,name:"Partner Pipeline Update",description:"The recurring pipeline update, written from what actually happened. Town reads the week's deal activity, tracker, and calendar, then drafts the update your partners, IC, or capital partners expect — what moved and why, what is at risk, what needs a decision, and what you are asking them for. Private draft, your edit, your send.",verified:!0,hidden:!0,requirements:["google"]},"pe-process-deadline-ledger":{id:"pe-process-deadline-ledger",agentSlug:"town-pe-process-deadline-ledger",version:2,name:"Process Deadline Register",description:"Process letters bury the dates that matter. Town reads them, plus your LOIs, NDAs, and exclusivity terms, and keeps one dated ledger of every IOI date, bid deadline, management meeting, exclusivity expiry, and financing commitment date across your live processes — with early warnings while there is still time to act.",verified:!0,hidden:!0,requirements:["google"]},"person-sweep":{id:"person-sweep",agentSlug:"town-person-sweep",version:12,name:"Person Sweep",description:"Discovers key people the user communicates and collaborates with from email and calendar, then researches each one to pre-populate relationship profiles",verified:!0,adminOnly:!0,requirements:["google"],subagentSlugs:["town-research-person"]},"persona-deep-classifier":{id:"persona-deep-classifier",agentSlug:"town-persona-deep-classifier",version:12,name:"Persona Deep Classifier",description:"Re-classifies the user's professional role from their Knowledge wiki, calendar, and email once the wiki is built, and proposes ways to make the onboarding classifier more accurate.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"persona-tab":{id:"persona-tab",agentSlug:"town-persona-tab",version:4,name:"Persona Tab",description:"Each week, names the work personas the user belongs to and writes up to 12 prompt cards grounded in their own evidence, at most 4 per persona. Read only; the For You tab shows the cards.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"personal-assistant":{id:"personal-assistant",agentSlug:"town-personal-assistant",version:271,name:"Personal Assistant",description:"General-purpose assistant that responds to emailed requests and can perform various tasks including agent monitoring",verified:!0,adminOnly:!0,requirements:["google"],subagentSlugs:["town-general-purpose","town-research-person","town-write-in-user-voice","town-meeting-review","town-browser-driver"]},"pgm-board-honesty-check":{id:"pgm-board-honesty-check",agentSlug:"town-pgm-board-honesty-check",version:2,name:"Tracker Honesty Check",description:"Every Monday morning, Town reads the tracker behind your programs and reports the items that are no longer telling the truth - due dates that passed with the status untouched, work in progress that nobody has moved in weeks, blocked items with no blocker named, and items with no owner at all.",verified:!0,hidden:!0,requirements:["google"]},"pgm-program-status-draft":{id:"pgm-program-status-draft",agentSlug:"town-pgm-program-status-draft",version:2,name:"Program Status Draft",description:"Late each week, Town rebuilds what actually moved on each workstream from your tracker, threads, and meetings, states a status only where the evidence supports one, lists the milestone dates that changed since your last report, and saves the status update unsent for you to edit and send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pgm-review-decision-heads-up":{id:"pgm-review-decision-heads-up",agentSlug:"town-pgm-review-decision-heads-up",version:2,name:"Cross-Team Heads-Up",description:"When a program review or cross-team sync finishes transcribing, Town pulls out what actually changed - decisions made, dates moved, dependencies added - works out which teams were not in the room but are on the hook, and saves one short unsent heads-up per team plus a decision log entry.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pgm-scope-creep-watch":{id:"pgm-scope-creep-watch",agentSlug:"town-pgm-scope-creep-watch",version:2,name:"Scope Drift Watch",description:"Once a week, Town re-reads the threads on your programs for work that was added to the plan without going through change control - a new requirement, an extra environment, a pulled-in date - names who asked, who agreed, and which milestone it lands on, and can draft the change request reply for you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pgm-thread-work-capture":{id:"pgm-thread-work-capture",agentSlug:"town-pgm-thread-work-capture",version:2,name:"Untracked Work Catcher",description:"Twice each weekday, Town re-reads the mail and Slack on your programs for work that got handed to someone - in a reply, in passing, or to a third party - checks whether the tracker already has it, and proposes the missing items for your approval with an owner, a date, and the sentence they came from.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pm-gtm-change-heads-up":{id:"pm-gtm-change-heads-up",agentSlug:"town-pm-gtm-change-heads-up",version:2,name:"GTM Change Heads-Up",description:"Each week, finds the customer-visible changes dated to land soon, translates each into plain language with the affected segment and a reusable line, and saves an unsent enablement note for sales and support.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pm-launch-blocker-chase":{id:"pm-launch-blocker-chase",agentSlug:"town-pm-launch-blocker-chase",version:2,name:"Launch Blocker Chase",description:"Each weekday, reconstructs the open dependencies behind your in-flight product work, names the owner and the missing input for each one, and saves unsent nudges for the asks that have gone quiet.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pm-leadership-product-update":{id:"pm-leadership-product-update",agentSlug:"town-pm-leadership-product-update",version:2,name:"Leadership Product Update",description:"Late each week, reconstructs what shipped, moved, and slipped across the initiatives you own, compares the dates against what you last communicated, and saves an unsent update that leads with the decisions you need.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pm-shipped-request-loop-close":{id:"pm-shipped-request-loop-close",agentSlug:"town-pm-shipped-request-loop-close",version:2,name:"Shipped Request Drafts",description:"Each week, matches what just shipped against the requests customers made months ago and saves a short unsent reply, in the original thread, to each person whose exact ask is now live.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pm-user-call-feedback-capture":{id:"pm-user-call-feedback-capture",agentSlug:"town-pm-user-call-feedback-capture",version:2,name:"User Call Feedback Logger",description:"When a customer or user call transcript is ready, extracts the requests, pain, and workarounds that were actually said, matches them to existing themes, and files them to your feedback record with tracker writes held for approval.",verified:!0,hidden:!0,requirements:["google"]},"pmm-battlecard-refresh":{id:"pmm-battlecard-refresh",agentSlug:"town-pmm-battlecard-refresh",version:2,name:"Battlecard Update",description:"Each week, reads your own win-loss notes, deal threads, and call notes for what competitors are really doing to you, compares that against each battlecard, and saves a proposed revision plus a short note sales can read, without editing the live card.",verified:!0,hidden:!0,requirements:["google"]},"pmm-buyer-language-evidence":{id:"pmm-buyer-language-evidence",agentSlug:"town-pmm-buyer-language-evidence",version:2,name:"Buyer Language Evidence",description:"When an external customer or prospect call transcript is ready, pulls the buyer's own short phrasings for the problem, the alternatives, and the objection, files them into a living evidence document for that segment, and marks which lines of your current messaging they support or contradict.",verified:!0,hidden:!0,requirements:["google"]},"pmm-gtm-leadership-update":{id:"pmm-gtm-leadership-update",agentSlug:"town-pmm-gtm-leadership-update",version:2,name:"GTM Leadership Update",description:"Sunday evening, reconstructs the week across your go-to-market workstreams from calls, threads, docs, and connected Slack, then saves your section of the leadership update in last week's format and your own voice, ready to paste.",verified:!0,hidden:!0,requirements:["google"]},"pmm-launch-readiness-chase":{id:"pmm-launch-readiness-chase",agentSlug:"town-pmm-launch-readiness-chase",version:2,name:"Launch Readiness Chase",description:"Each weekday, reads your launch workback plan, finds the gates that are overdue, unowned, or quietly at risk before the ship date, and saves a short nudge draft for each owner instead of leaving you to reconstruct the plan yourself.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"pmm-speaking-sponsorship-screen":{id:"pmm-speaking-sponsorship-screen",agentSlug:"town-pmm-speaking-sponsorship-screen",version:2,name:"Speaking & Sponsorship Screen",description:"Twice a weekday, picks the conference, webinar, sponsorship, and event-partnership asks out of your mail, researches who is really behind them, checks the dates against your calendar, and hands you a yes or no with the reply already drafted.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"post-meeting-agreed-work":{id:"post-meeting-agreed-work",agentSlug:"town-post-meeting-agreed-work",version:3,name:"Meeting Action Hand-Off",description:"After a meeting finishes transcribing, Town separates what was actually agreed from what was merely discussed, checks it against the work already tracked for each owner, and proposes only the genuinely new items as Town tasks or Linear issues. Anything you personally promised comes back as an unsent draft, internal Slack routing waits for your approval, and one private handoff summary records the whole pass.",verified:!0,hidden:!1,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"post-signup-engagement-email":{id:"post-signup-engagement-email",agentSlug:"town-post-signup-engagement-email",version:4,name:"Post-Signup Engagement Email",description:"Sends personalized post-signup engagement emails to new users.",verified:!0,adminOnly:!0,requirements:["google"]},"procure-commit-date-watch":{id:"procure-commit-date-watch",agentSlug:"town-procure-commit-date-watch",version:2,name:"Commit Date Watch",description:"Twice each weekday, rebuilds the orders you placed from the supplier's own messages and surfaces the two things that break a plan quietly: the order the supplier never gave a date for, and the date a supplier moved without telling anyone who depends on it. Turn drafts on and it writes one confirmation ask per supplier and leaves it unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"procure-invoice-po-match":{id:"procure-invoice-po-match",agentSlug:"town-procure-invoice-po-match",version:2,name:"Invoice Match Check",description:"Twice each weekday, reads the supplier invoices that arrived, matches each line against the order and quote you actually agreed, and reports the price, quantity, freight, and duplicate-number gaps with the supplier query already drafted for the ones that fail.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"procure-requisition-stall-chase":{id:"procure-requisition-stall-chase",agentSlug:"town-procure-requisition-stall-chase",version:2,name:"Stalled Requisition Chase",description:"Twice each weekday, walks the purchase requests sitting in your queue, says which are missing the fields you need, which have aged out with a named approver, and which are actually waiting on you, and saves the clarifying reply and the approver nudge unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"procure-supplier-call-followthrough":{id:"procure-supplier-call-followthrough",agentSlug:"town-procure-supplier-call-followthrough",version:2,name:"Supplier Call Follow-Through",description:"When a supplier call finishes transcribing, pulls out only the actions both sides agreed to with an owner and a date, saves a short confirmation email for review, and submits the same actions to your supplier action log for approval. Commercial terms are flagged for you, never confirmed back to the supplier.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"procure-weekly-supply-update":{id:"procure-weekly-supply-update",agentSlug:"town-procure-weekly-supply-update",version:2,name:"Weekly Supply Update",description:"Every Monday morning, rebuilds what is landing this week, what slipped and what it blocks, what is still waiting on an approval or a quote, and which decisions are yours to ask for, and leaves the whole update drafted to your operations and finance group, unsent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"product-update-notifier":{id:"product-update-notifier",agentSlug:"town-product-update-notifier",version:10,name:"Product Update Notifier",description:"Judges which approved product updates are relevant to this user and sends at most one personalized update email — or stays silent.",verified:!0,adminOnly:!0,requirements:["google"]},"project-close-chaser":{id:"project-close-chaser",agentSlug:"town-project-close-chaser",version:2,name:"Project Close Chaser",description:"The work shipped weeks ago and the project is still open: one round of feedback never came, two assets were never sent over, the sign-off never arrived, the final invoice was never paid. Three mornings a week this finds those open items on projects you have already delivered, drafts one short chase to the person who owes each one, and stops chasing as soon as the thread shows it landed.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"project-open-items-log":{id:"project-open-items-log",agentSlug:"town-project-open-items-log",version:2,name:"Project Open-Items Log",description:"After a project call ends, the per-project log updates itself from the notes and the threads: what got decided, what is still open on the GC, and which decisions the job is waiting on you for, with how long each one has been sitting. Rows for your own tracker are proposed for approval, and nothing is sent to anyone.",verified:!0,hidden:!0,requirements:["google"]},"project-tracker":{id:"project-tracker",agentSlug:"town-project-tracker",version:14,name:"Project Tracker",description:"Each night, reviews the user's signals (sent emails, Slack, calendar, routine activity, memories) to map the projects they're actively working on, logs the tracked project set with status, and keeps the Projects directory in their Knowledge wiki up to date.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"property-invoice-routing":{id:"property-invoice-routing",agentSlug:"town-property-invoice-routing",version:3,name:"Property Invoice Routing",description:"Three times a day, finds the vendor invoices, utility bills, and payment notices that landed for your properties, reads the attachment for vendor, amount, due date, and property, and leaves a forward draft addressed to whoever pays that class of bill with the file still attached. Each one is queued as a row for your payables tracker, waiting on your approval before it writes.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"property-report-variance-watch":{id:"property-report-variance-watch",agentSlug:"town-property-report-variance-watch",version:2,name:"Property Report Variance Watch",description:"Twice a weekday, finds the operating reports, rent rolls, audit summaries, and fund statements that arrived as attachments, reads the actual files instead of the email summary, and tells you what moved against budget and against last period. Where something needs an answer, the follow-up questions to the sender come back drafted for your review.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"provider-call-coverage-log":{id:"provider-call-coverage-log",agentSlug:"town-provider-call-coverage-log",version:2,name:"Call Coverage Log",description:"Before each weekday starts, reads your roster and swap mail against your own calendar and reports the three ways coverage goes wrong: a shift you agreed to that never reached your calendar, a coverage ask nobody has answered, and a swap agreed in mail that the posted roster still contradicts. Turn replies on and it drafts an answer to the asks waiting on you. It never accepts, declines, or commits to a shift for you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"provider-cme-credit-ledger":{id:"provider-cme-credit-ledger",agentSlug:"town-provider-cme-credit-ledger",version:2,name:"CME Credit Ledger",description:"One running ledger of the continuing education credits you can actually prove, rebuilt on the second morning of each month from the course completions, conference confirmations, and certificates already sitting in your mail. It shows credits banked against the requirement you set, how long the cycle has left, and which activities you attended but have no certificate for. It is a working ledger, never the official record, and it never files or claims a credit on your behalf.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"provider-colleague-reply-drafts":{id:"provider-colleague-reply-drafts",agentSlug:"town-provider-colleague-reply-drafts",version:2,name:"Colleague Reply Drafts",description:"Other clinicians and outside offices write to you about shared care, and the reply waits because part of it has to be yours. Three times each weekday, finds those threads where the last message is not yours and something is being asked, and saves one unsent reply per thread covering the administrative part: what you can confirm, when the letter will follow, or which document is still missing. Anything that needs your clinical words is marked as yours to write and left blank.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"provider-paperwork-due-list":{id:"provider-paperwork-due-list",agentSlug:"town-provider-paperwork-due-list",version:2,name:"Paperwork Due List",description:"Forms, reports, and attestations arrive with a date on them and then go quiet in the inbox until someone chases. Every Tuesday and Friday morning, rebuilds the paperwork third parties are waiting on you to complete, records who is waiting, the date it is due, and what is still missing to finish it, and keeps one private list in your own Town space. It never completes or signs anything, and it never writes a patient into the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"provider-referral-loop-watch":{id:"provider-referral-loop-watch",agentSlug:"town-provider-referral-loop-watch",version:2,name:"Referral Loop Watch",description:"Twice each weekday, rebuilds the referrals, outside studies, and records requests you sent from your own mail, works out which ones have produced nothing back yet, and reports them ranked by how long they have been open. Turn asks on and it saves one unsent status note per open request. It names the office and the thread, never the patient, and never opens the contents of a report that did come back.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"realtor-client-search-log":{id:"realtor-client-search-log",agentSlug:"town-realtor-client-search-log",version:2,name:"Client Search Log",description:"Buyers and tenants ask the same question in a dozen different ways: what happened to the one on the corner? The answer lives in four threads, a calendar entry, and a reply you read on a phone three weeks ago. Twice a week, Town rebuilds one living shortlist per active client from the properties you sent, the tours you booked, and what each client said back, marks where every property stands and why, and keeps it in a Town document you can read from or paste into a reply.",verified:!0,hidden:!0,requirements:["google"]},"realtor-contract-close-chase":{id:"realtor-contract-close-chase",agentSlug:"town-realtor-contract-close-chase",version:2,name:"Contract-to-Close Chase",description:"A transaction rarely falls apart on the closing date. It falls apart on the Tuesday nobody noticed the inspection period was ending, or the week the lender never confirmed the appraisal had been ordered. Each weekday morning, Town rebuilds every deal you have under contract from the executed agreement and the threads around it, reports which milestone each one is waiting on and which party owes it, and drafts one chase note per party on each deal. Every date shown carries the message or calendar entry it came from.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"realtor-inquiry-reply-chase":{id:"realtor-inquiry-reply-chase",agentSlug:"town-realtor-inquiry-reply-chase",version:2,name:"Inquiry Reply Chase",description:"Three times each weekday, Town collects the buyer, seller, and tenant inquiries that reached your inbox through listings, referrals, and portal forwards, and keeps the two that cost you business: the first message nobody answered, and the conversation that went quiet after one reply. Each one is tied to the property or search it asks about and checked against your calendar for a showing that was actually booked. It writes one reply per person and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"realtor-showing-feedback-drafts":{id:"realtor-showing-feedback-drafts",agentSlug:"town-realtor-showing-feedback-drafts",version:2,name:"Showing Feedback Drafts",description:"When a showing, listing appointment, or client consult ends, the two notes that matter are owed immediately and written last, usually from memory, in a car, between appointments. Town reads the invite, the thread that scheduled it, and any recording you kept, pulls what your client actually reacted to, and saves the note to your client. Where you were the visiting side, it also saves the showing feedback the listing agent is waiting on, written to say what your client thought without saying what your client will do.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"realtor-weekly-seller-update":{id:"realtor-weekly-seller-update",agentSlug:"town-realtor-weekly-seller-update",version:2,name:"Weekly Seller Update",description:"Sellers measure an agent by the update they get after a weekend, and it is the first thing to fall off a Monday that starts at seven. Every Monday morning, Town reconstructs the past week on each of your active listings from showing confirmations, feedback that came back, inquiries received, and the marketing that actually ran, then saves one update per seller. Every line is something a message or a calendar entry supports, and a quiet week is reported as a quiet week rather than padded.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-candidate-reply-next-step":{id:"recruiting-candidate-reply-next-step",agentSlug:"town-recruiting-candidate-reply-next-step",version:3,name:"Candidate Next-Step Drafts",description:"Three times a weekday, every new candidate reply on your outreach threads gets read and answered with the right next step: proposed interview times from your real calendar, the role spec they asked for, or a short assessment of where they actually fit. Every reply is saved as a draft in its own thread and nothing is sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-going-cold":{id:"recruiting-going-cold",agentSlug:"town-recruiting-going-cold",version:2,name:"Going cold",description:"Each weekday morning, finds candidates, interviewers, and hiring managers who owe you a reply, writes up to 5 short follow-ups as drafts in your inbox, and emails you the list. It never sends anything, and it stays quiet when nothing has stalled.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-interview-scorecard-capture":{id:"recruiting-interview-scorecard-capture",agentSlug:"town-recruiting-interview-scorecard-capture",version:2,name:"Interview Scorecard",description:"When a screen or interview ends, the notes and transcript are turned into a written scorecard against your own criteria: what held up, what is missing, and the recommendation. The pipeline row is prepared for approval and an internal debrief is drafted, all within the hour.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-keep-record-true":{id:"recruiting-keep-record-true",agentSlug:"town-recruiting-keep-record-true",version:2,name:"Keep the Record True",description:"After recruiting meetings and twice each weekday, finds candidate updates in your email, calendar, and meeting notes, like a withdrawal or a stage move. Emails you each one with its source, then asks before changing your connected ATS. Otherwise, gives you a list to copy in.",verified:!0,hidden:!0,requirements:["google"]},"recruiting-pipeline-analysis":{id:"recruiting-pipeline-analysis",agentSlug:"town-recruiting-pipeline-analysis",version:2,name:"Pipeline Analysis",description:"Every Friday afternoon, builds a recruiting metrics report from your ATS (if connected), email, and calendar: candidates by stage, pass-through, time in stage, offers, interview hours, and reply speed. Saves a Town doc and emails you the highlights. No candidate names, so you can share it.",verified:!0,hidden:!0,requirements:["google"]},"recruiting-post-interview-candidate-note":{id:"recruiting-post-interview-candidate-note",agentSlug:"town-recruiting-post-interview-candidate-note",version:2,name:"Post-Interview Candidate Follow-Up",description:"Forty-five minutes after a candidate interview ends, the conversation and the candidate's own email thread are read, and one candidate-facing follow-up is drafted in that thread: advancing, holding with an honest timeline, or closing gracefully. Internal scorecard language, debrief opinions, and compensation detail never reach the draft, and nothing is sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-sourcing-outreach-nudge":{id:"recruiting-sourcing-outreach-nudge",agentSlug:"town-recruiting-sourcing-outreach-nudge",version:2,name:"Sourcing Outreach Nudge",description:"Each weekday morning, your sent outreach is checked for role proposals, intro offers, and candidate approaches that never got an answer. Each one that has been silent past your threshold comes back as a short follow-up draft written in your voice, capped so nobody is chased twice.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-weekly-pipeline-update":{id:"recruiting-weekly-pipeline-update",agentSlug:"town-recruiting-weekly-pipeline-update",version:2,name:"Weekly Pipeline Update",description:"Every Friday morning, writes your weekly pipeline update: a full readout for you, saved in Town, and a draft email for each hiring manager, client, or portfolio founder covering only their roles. The drafts wait in your inbox for you to review and send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"recruiting-weekly-search-update":{id:"recruiting-weekly-search-update",agentSlug:"town-recruiting-weekly-search-update",version:2,name:"Weekly Search Update",description:"Early Monday, each active search gets its own drafted update built from what actually happened last week: profiles submitted, interviews held and their outcomes, candidates who moved or dropped, and what you need from the client. One draft per client, each in its own thread, none of them sent.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"retail-late-purchase-orders":{id:"retail-late-purchase-orders",agentSlug:"town-retail-late-purchase-orders",version:2,name:"Purchase Order Chaser",description:"Each weekday, reconstructs the orders you placed with suppliers from their own confirmations, checks which ones are past their promised ship date with no shipping notice, and sends you one ranked late list with a chase draft held for each supplier.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"retail-supplier-terms-confirmation":{id:"retail-supplier-terms-confirmation",agentSlug:"town-retail-supplier-terms-confirmation",version:2,name:"Supplier Terms Confirmation",description:"When a supplier or buyer call finishes transcribing, pulls out the commercial terms you actually agreed, unit price, minimum quantity, lead time, ship window, payment terms, saves a short confirmation email for review, and adds the same terms to your terms log for approval.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"retail-vendor-request-handoff":{id:"retail-vendor-request-handoff",agentSlug:"town-retail-vendor-request-handoff",version:2,name:"Vendor Request Hand-Off",description:"A few times a day, finds the vendor, supplier, and storefront messages that need someone other than you to do something, and saves a forward to that person with a one-line summary and the exact instruction, ready for you to glance at and send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"retail-weekly-store-recap":{id:"retail-weekly-store-recap",agentSlug:"town-retail-weekly-store-recap",version:2,name:"Weekly Store Recap",description:"At the end of the week, rebuilds what actually happened in the business from order, refund, and payout notices, your inventory sheet, and the week's manager threads, then saves the recap you owe your partner or your store managers as an unsent draft.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"retail-wholesale-reorder-nudge":{id:"retail-wholesale-reorder-nudge",agentSlug:"town-retail-wholesale-reorder-nudge",version:2,name:"Wholesale Reorder Nudge",description:"Every Monday, works out which wholesale and repeat accounts are overdue against their own reorder rhythm, and saves each one a short reorder email pre-filled with the items and quantities they usually take, so you approve instead of writing.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sales-close-plan-keeper":{id:"sales-close-plan-keeper",agentSlug:"town-sales-close-plan-keeper",version:2,name:"Close Plan Tracker",description:"Twice a week, rebuilds the close plan for every late-stage deal from what was actually agreed, keeps one living status doc of who owes which step by when, and drafts the nudge for each step that has gone past its date.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sales-forecast-update-draft":{id:"sales-forecast-update-draft",agentSlug:"town-sales-forecast-update-draft",version:2,name:"Weekly Forecast Update",description:"Every week, checks each committed and best-case deal against the meetings and replies that actually happened, then saves the forecast update you owe, with the deals whose dates the evidence does not support called out before someone else finds them.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sales-post-call-deal-record":{id:"sales-post-call-deal-record",agentSlug:"town-sales-post-call-deal-record",version:2,name:"Post-Call Deal Update",description:"Shortly after each external prospect call, reconstructs what actually changed on the deal from your notes, the thread, and the meeting, and hands you a field-by-field update ready to paste into the CRM, or writes it to your pipeline sheet with your approval.",verified:!0,hidden:!0,requirements:["google"]},"sales-quiet-deal-chase":{id:"sales-quiet-deal-chase",agentSlug:"town-sales-quiet-deal-chase",version:2,name:"Quiet Deal Chaser",description:"Twice a week, finds the open deals where the prospect owes you a reply, works out what the last real ask was, and saves one short follow-up draft per deal plus a ranked list of who has gone quiet on you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sales-win-back-signal-sweep":{id:"sales-win-back-signal-sweep",agentSlug:"town-sales-win-back-signal-sweep",version:2,name:"Win-Back Signal Sweep",description:"Every week, sweeps the closed-lost deals in your pipeline for the few where a concrete, dated new reason has appeared since the loss, and saves one personalized win-back draft per qualified deal. Deals with nothing new stay closed.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"schedule-assist":{id:"schedule-assist",agentSlug:"town-schedule-assist",version:63,name:"Auto-schedule",description:"Detects meeting requests and drafts replies with available times, checking all your calendars to avoid conflicts",verified:!0,deprecated:!0,replacedBy:"town-auto-inbox",hidden:!0,requirements:["google"],subagentSlugs:["town-research-person","town-write-in-user-voice"]},"schedule-optimizer":{id:"schedule-optimizer",agentSlug:"town-schedule-optimizer",version:8,name:"Schedule Optimizer",description:"Looks at weeks ahead, finds ways to make days more efficient — clusters meetings, protects focus time, flags back-to-backs, and suggests reschedules.",verified:!0,requirements:["google"]},"scheduling-driver":{id:"scheduling-driver",agentSlug:"town-scheduling-driver",version:4,name:"Scheduling Driver",description:"Runs one external scheduling negotiation end to end: watches the effort, reads its calendar context, and moves the negotiation forward as counterparties reply.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:["town-scheduling-drafter","town-scheduling-signal-extractor","town-scheduling-ask"]},"sdr-circle-back-callbacks":{id:"sdr-circle-back-callbacks",agentSlug:"town-sdr-circle-back-callbacks",version:2,name:"Prospect Callback Chaser",description:"Every prospect who told you to come back later gets a date and a reason. Each week this finds the ones now due, checks whether anything actually changed at their company, and drafts the callback that opens with the new reason rather than just checking in.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sdr-demo-confirmation-sweep":{id:"sdr-demo-confirmation-sweep",agentSlug:"town-sdr-demo-confirmation-sweep",version:3,name:"Demo Confirmation Sweep",description:"Each afternoon, looks at the prospect meetings coming up, scores which ones are wobbling on unaccepted invites, silence since booking, or a long gap between booking and the date, and drafts the confirmation that gets them to show up.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sdr-meeting-handoff-brief":{id:"sdr-meeting-handoff-brief",agentSlug:"town-sdr-meeting-handoff-brief",version:2,name:"AE Hand-Off Brief",description:"After a discovery or intro call, turns the conversation into the qualification record the person taking the next meeting actually needs: pain, buying roles, timeline, current tooling, the agreed next step, and the questions still open, written up and left as a draft for you to send.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sdr-outbound-weekly-update":{id:"sdr-outbound-weekly-update",agentSlug:"town-sdr-outbound-weekly-update",version:3,name:"Weekly Outbound Update",description:"Every Friday, rebuilds your week from the meetings you held, the replies you got, and whatever your CRM or tracker shows, splits it the way your team reports it, compares it with your pace, and writes the update as a draft rather than making you assemble it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"sdr-prospect-reply-drafts":{id:"sdr-prospect-reply-drafts",agentSlug:"town-sdr-prospect-reply-drafts",version:2,name:"Prospect Reply Drafts",description:"A few times each workday, finds the prospects who replied to your outbound and the inbound demo requests that landed, reads the whole thread plus your prior history with that company, and leaves a personalized reply drafted in your voice on each thread. Nothing sends.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"search-firm-client-writeup":{id:"search-firm-client-writeup",agentSlug:"town-search-firm-client-writeup",version:3,name:"Client Write-Up Drafts",description:"After each candidate interview, the client-ready write-up is drafted from the call transcript in your rubric and your voice, as an email draft to your client with the recommendation left for you to fill. Nothing is sent to the client. An Ashby or Notion tracker entry waits for your approval in Town; a Google Sheet only you can access is updated directly, and your report names the entry.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"search-firm-market-map":{id:"search-firm-market-map",agentSlug:"town-search-firm-market-map",version:3,name:"Market Map",description:"Hand it a search thesis and it builds the company long list that thesis implies, writing each company into your own Google Sheet or Notion with a public source behind every row. For the companies you name, it finds who held the target seat during the window that matters, not today's title-holder. Nothing is sent to anyone.",verified:!0,hidden:!0,requirements:["google"]},"search-firm-weekly-client-update":{id:"search-firm-weekly-client-update",agentSlug:"town-search-firm-weekly-client-update",version:3,name:"Weekly Client Update",description:"Every Monday morning, each active search gets an unsent client update drafted from your tracker and mailbox: what moved, interviews and their outcomes, who advanced or dropped, and what you need from the client. A client who has gone quiet since a submittal or intro gets a drafted nudge, each client sync this week gets a briefing, and nothing sends until you send it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"strategy-coverage-rollup":{id:"strategy-coverage-rollup",agentSlug:"town-strategy-coverage-rollup",version:2,name:"Weekly Coverage Update",description:"Real movement on every name you cover.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"strategy-expert-call-log":{id:"strategy-expert-call-log",agentSlug:"town-strategy-expert-call-log",version:2,name:"Expert Call Log",description:"Every conversation files itself into your record.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"strategy-inbound-deal-screen":{id:"strategy-inbound-deal-screen",agentSlug:"town-strategy-inbound-deal-screen",version:2,name:"Inbound Deal Screen",description:"Every real opportunity lands in your tracker.",verified:!0,hidden:!0,requirements:["google"]},"strategy-model-assumption-recheck":{id:"strategy-model-assumption-recheck",agentSlug:"town-strategy-model-assumption-recheck",version:2,name:"Model Assumption Audit",description:"Every assumption rechecked against the source you cited.",verified:!0,hidden:!0,requirements:["google"]},"strategy-recommendation-adoption":{id:"strategy-recommendation-adoption",agentSlug:"town-strategy-recommendation-adoption",version:2,name:"Recommendation Adoption Tracker",description:"You get the evidence behind every verdict.",verified:!0,hidden:!0,requirements:["google"]},"student-course-deadline-board":{id:"student-course-deadline-board",agentSlug:"town-student-course-deadline-board",version:2,name:"Coursework Deadline Board",description:"Twice a week, Town rebuilds one deadline board for every course you are taking. It reads your syllabi, the course announcements sitting in your mail, and your calendar, then writes each assignment, exam, lab, and draft into a single dated register with the source it came from. When a professor moves a date by email, the board flags the change instead of quietly overwriting it, and every edit waits for your approval before it lands.",verified:!0,hidden:!0,requirements:["google"]},"student-financial-aid-paperwork":{id:"student-financial-aid-paperwork",agentSlug:"town-student-financial-aid-paperwork",version:2,name:"Financial Aid Paperwork",description:"Twice a week, Town reads the mail from your financial aid office, scholarship programs, the bursar, and the registrar, and pulls out the one thing that matters in each: the document they are waiting on from you, and the date they need it by. Verification forms, tax transcripts, enrollment proof, renewal reports, holds blocking registration. Each item comes back as a checklist with the exact wording they used, and you can have the reply drafted too.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"student-group-project-ledger":{id:"student-group-project-ledger",agentSlug:"town-student-group-project-ledger",version:2,name:"Group Project Ledger",description:"Every Monday and Thursday, Town turns your group project threads into a plain ledger: who said they would do which part, what has actually landed, who has gone quiet since the last check, and how many days are left before the group submits. Your own commitments are on the list too. Turn drafting on and it writes one short message to the group thread naming the open parts, and leaves it in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"student-letter-request-chase":{id:"student-letter-request-chase",agentSlug:"town-student-letter-request-chase",version:2,name:"Letters You Are Waiting On",description:"Every weekday morning, Town lines up the recommendation letters and references you have asked people for: who agreed, which deadline each letter is attached to, whether the portal has confirmed it arrived, and how many days are left. It drafts the polite reminder at the point the advice says to send one, about two weeks out and again a few days out, in the same thread you asked in, and leaves it unsent for you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"student-professor-thread-chase":{id:"student-professor-thread-chase",agentSlug:"town-student-professor-thread-chase",version:2,name:"Professor Reply Chase",description:"Twice each weekday, Town re-reads the emails you sent your professors and TAs and keeps only the ones that never got a real answer: the question about the problem set, the regrade you asked for, the extension you requested, the accommodation letter nobody confirmed. Each one comes back with the course, what you asked, how long it has been quiet, and the class date it affects. Turn drafting on and it writes a short, polite follow-up in the same thread and leaves it in your drafts.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"support-escalation-stall-chase":{id:"support-escalation-stall-chase",agentSlug:"town-support-escalation-stall-chase",version:2,name:"Escalation Stall Chase",description:"Once a case leaves your hands for another team, two clocks start: how long that team has been silent, and how long the customer has been waiting to hear anything. On Monday, Wednesday, and Friday, this rebuilds the cases you handed off, keeps the ones where the internal side has gone quiet past your limit, ranks them by the customer's wait rather than the age of the internal thread, and saves one unsent nudge per stalled case on that case's own internal thread.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"support-help-article-gaps":{id:"support-help-article-gaps",agentSlug:"town-support-help-article-gaps",version:2,name:"Help Article Gaps",description:"The third time you type the same answer, it stopped being a reply and became an article nobody has written. Every Tuesday, this groups the questions you have answered from scratch across recent customer threads, counts how often each one came back, checks whether your existing documents already cover it, and turns the strongest of your own past answers into one draft article per real gap.",verified:!0,hidden:!0,requirements:["google"]},"support-promised-update-drafts":{id:"support-promised-update-drafts",agentSlug:"town-support-promised-update-drafts",version:2,name:"Promised Update Drafts",description:"Reads back your own replies for the places where you told a customer you would come back to them, records what you promised and the day you named, and each weekday morning brings forward every promise now due or already past. Each one arrives with an update built from what actually happened since, saved unsent in the thread it came from. Where nothing moved, the update says so and asks for time instead of inventing progress.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"support-response-clock-watch":{id:"support-response-clock-watch",agentSlug:"town-support-response-clock-watch",version:2,name:"Response Clock Watch",description:"Three times each weekday, rebuilds the customer conversations where the customer spoke last and nobody has answered, ages each one against the response targets you set, and ranks what is closest to breaking them. A thread a teammate already answered drops off the list, and a thread with a call already booked is held rather than chased. With acknowledgments on, it saves one short unsent reply for each thread already past its target.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"support-weekly-update":{id:"support-weekly-update",agentSlug:"town-support-weekly-update",version:2,name:"Weekly Support Update",description:"At the end of each week, reconstructs the week the queue actually had from your own mail and calendar: how much came in and what it was about, the two or three problems that drove the volume, what slipped past a target, what is still sitting with another team, and the one thing you need a decision on. It copies the shape of the update you already send and is saved unsent for you to edit.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"team-power-recommender":{id:"team-power-recommender",agentSlug:"town-team-power-recommender",version:3,name:"Team Power Recommender",description:"Maps the user's teams and reads their connected work records to recommend which of the user's powers to share with each teammate and which new powers to create, each with evidence-backed rationale, confidence, and ready-to-paste install or build prompts. Recommends only; it never shares, creates, sends, or modifies anything on its own.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"test-timezone-upgrade":{id:"test-timezone-upgrade",agentSlug:"town-test-timezone-upgrade",version:4,name:"Test Timezone Upgrade",description:"Internal test agent for verifying timezone preservation during upgrades. Not for end users.",verified:!1,adminOnly:!0,requirements:[]},"text-announcement-evaluator":{id:"text-announcement-evaluator",agentSlug:"town-text-announcement-evaluator",version:1,name:"Text Announcement Evaluator",description:"Evaluates an operator-triggered announcement and proposes or publishes one relevant text.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"travel-booking-organizer":{id:"travel-booking-organizer",agentSlug:"town-travel-booking-organizer",version:11,name:"Travel & Booking Organizer",description:"Detects flight confirmations and hotel bookings, labels them, extracts key details, and logs everything to a Google Sheet.",verified:!0,hidden:!0,requirements:["google"]},"urgency-router":{id:"urgency-router",agentSlug:"town-urgency-router",version:4,name:"Urgency Router",description:"Classifies queued alerts and follows the user's alert threshold and delivery preference.",verified:!0,adminOnly:!0,hidden:!0,requirements:["google"]},"user-profile-builder":{id:"user-profile-builder",agentSlug:"town-user-profile-builder",version:55,name:"User Profile Builder",description:"Analyzes sent emails to build a user profile that helps all agents understand who you are and how you communicate",verified:!0,adminOnly:!0,requirements:["google"],subagentSlugs:[]},"uxr-incentive-followthrough":{id:"uxr-incentive-followthrough",agentSlug:"town-uxr-incentive-followthrough",version:2,name:"Incentive Follow-Through",description:"About an hour after a research session ends, Town works out whether that event really was a participant session, then handles only what the participant is owed afterwards: the incentive your policy promises, the thank-you, and anything you said you would send. It also re-checks recent sessions whose incentive has no evidence of ever going out, so the person who quietly never got paid surfaces instead of waiting for a complaint. It never reads, summarizes, or quotes what was said in the session.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"uxr-participant-funnel-tracker":{id:"uxr-participant-funnel-tracker",agentSlug:"town-uxr-participant-funnel-tracker",version:2,name:"Participant Funnel Tracker",description:"Recruiting for a study leaks quietly, one unanswered screener at a time. Each weekday morning, Town rebuilds the funnel for every study you have in field from your own mail, calendar, and recruiting log, puts each person at the stage the evidence supports, and reports the gap between where you are and the quota you set. It names the people who have sat at one stage too long, the segments still short, and the days of field time left, without recording a single screener answer.",verified:!0,hidden:!0,requirements:["google"]},"uxr-readout-decision-chase":{id:"uxr-readout-decision-chase",agentSlug:"town-uxr-readout-decision-chase",version:2,name:"Readout Decision Chase",description:"The readout lands, the room nods, and then nothing moves. Two mornings a week, Town re-reads the share-outs you sent, pulls out the specific calls each one asked someone to make and the follow-ups you promised in return, and reports both sides: the decisions still sitting with a named person past your waiting limit, and the cuts, clips, and links you still owe. It writes one short nudge per person on each share-out's own thread and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"uxr-research-request-intake":{id:"uxr-research-request-intake",agentSlug:"town-uxr-research-request-intake",version:2,name:"Research Request Intake",description:"A research ask rarely arrives as a brief. It arrives as one line inside somebody else's thread, with no decision attached and no date. Twice each weekday, Town picks those asks out of your mail, writes each one into a single intake list with the scoping answers it is still missing, and checks it against the studies you have already run so an answered question gets pointed at the answer instead of becoming a new project. It writes one clarifying reply per requester and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"uxr-unconfirmed-session-sweep":{id:"uxr-unconfirmed-session-sweep",agentSlug:"town-uxr-unconfirmed-session-sweep",version:2,name:"Unconfirmed Session Sweep",description:"Twice each weekday, Town re-reads the research sessions already on your calendar for the next few days and keeps only the ones that are not actually settled: the participant who never answered the invite, the consent form that never came back, the meeting link that no longer resolves, the timezone the participant wrote that does not match the one they were booked in, and the device or access requirement nobody confirmed. Each unsettled booking comes back with one short unsent note to that participant and a mark on the slots worth backfilling while a screened participant is still available.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"vc-board-meeting-prep":{id:"vc-board-meeting-prep",agentSlug:"town-vc-board-meeting-prep",version:4,name:"Board Meeting Prep",description:"Walk into a board meeting knowing exactly what to ask. Hand over the deck and financials (in chat, or by forwarding with a keyword) and get back the quarter-over-quarter numbers, a green/yellow/red read, sharp questions tied to specific figures, and investor takeaways — saved to Drive.",verified:!0,hidden:!0,requirements:["google"]},"vc-decision-backlog":{id:"vc-decision-backlog",agentSlug:"town-vc-decision-backlog",version:2,name:"Founder Decision Drafts",description:"Twice a week, find every founder who pitched you or sent a deck and is still waiting on an answer, rank them by how long they have waited and who made the introduction, and get a respectful pass or a specific next-step reply drafted for each one, held in your drafts for your edit.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"vc-pitch-deal-memo":{id:"vc-pitch-deal-memo",agentSlug:"town-vc-pitch-deal-memo",version:2,name:"Pitch Deal Memo",description:"When a pitch call finishes transcribing, turn it into a partner-ready memo - what the company does, the traction the founder stated, team, market as discussed, thesis fit, the risks worth raising, and the ask - saved privately in Town with every claim marked as stated or verified.",verified:!0,hidden:!0,requirements:["google"]},"vc-portfolio-update-chase":{id:"vc-portfolio-update-chase",agentSlug:"town-vc-portfolio-update-chase",version:2,name:"Portfolio Update Chaser",description:"Every week, check which portfolio companies have missed their reporting cadence, rank them by how long they have been silent and how much you have at stake, and get a short, friendly nudge drafted to each founder, held for your approval.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"vc-runway-risk-watch":{id:"vc-runway-risk-watch",agentSlug:"town-vc-runway-risk-watch",version:2,name:"Runway Risk Watch",description:"Every Monday, read the founder updates, board materials, and threads you already receive for the signals that matter - shrinking runway, rising burn, a key departure, a metric going the wrong way - and get a ranked risk list with the exact line each flag came from.",verified:!0,hidden:!0,requirements:["google"]},"vc-talent-fund-screen-scorecards":{id:"vc-talent-fund-screen-scorecards",agentSlug:"town-vc-talent-fund-screen-scorecards",version:2,name:"Fund Screen Scorecards",description:"When a screen for one of the fund's own roles is booked, its interview record is proposed in your pipeline with you as interviewer. When the screen ends, the scorecard is drafted from the call in the fund's own template, with the read left for you. Ashby and Notion writes wait for your approval in Town; a Google Sheet only you can access is updated directly, and every change is listed in an email to you. Town sends nothing to the candidate. With Ashby, approving an interview record may let Ashby send its own invites or reminders.",verified:!0,hidden:!0,requirements:["google"]},"vc-talent-intro-broker":{id:"vc-talent-intro-broker",agentSlug:"town-vc-talent-intro-broker",version:2,name:"Intro Broker",description:"Each weekday morning, every reply about an introduction you broker between a candidate and a portfolio company gets its next email drafted: the any-interest ask to the company contact, the direct intro once they opt in, or a kind pass note. When a direct intro has gone quiet for two weeks, a check-in is drafted. Each stage change goes to your network record: Ashby and Notion changes wait for your approval in Town, and a Google Sheet only you can access is updated directly, with every change listed in your report. Nothing sends until you send it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"vc-talent-network-courtship":{id:"vc-talent-network-courtship",agentSlug:"town-vc-talent-network-courtship",version:2,name:"Not-Now Reconnects",description:'Every Monday morning, catches the week\'s "not now, maybe later" replies, logs each with the timeframe the contact gave, and saves one unsent re-intro in the original thread when that time arrives. Your report carries the ledger and the favors owed both ways, and nothing sends until you send it.',verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"vc-talent-portfolio-search-update":{id:"vc-talent-portfolio-search-update",agentSlug:"town-vc-talent-portfolio-search-update",version:2,name:"Portfolio Search Update",description:"Every Friday morning, each open portfolio search gets an unsent update drafted for its GP or founder: what moved, what you need from them, a thirty-second read. The same run emails you what must be fixed before anyone finds it (candidates stuck in stage, interviews with no next step, threads gone dark, missing scorecards), and nothing sends until you send it.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"weekly-briefing":{id:"weekly-briefing",agentSlug:"town-weekly-briefing",version:4,name:"Weekly Briefing",description:"A weekly email previewing your week ahead — your calendar at a glance, emails that need attention, and a few suggested tasks",verified:!0,requirements:["google"]},"weekly-catch-up-recommender":{id:"weekly-catch-up-recommender",agentSlug:"town-weekly-catch-up-recommender",version:24,name:"Relationship Reconnect",description:"Searches sent emails weekly to find contacts you haven't connected with recently and recommends personalized messages to restart conversations.",verified:!0,requirements:["google"],subagentSlugs:["town-research-person","town-write-in-user-voice"]},"wellness-between-session-drafts":{id:"wellness-between-session-drafts",agentSlug:"town-wellness-between-session-drafts",version:2,name:"Between-Session Drafts",description:"Each weekday afternoon, rereads what you told clients you would send them: a handout, a form, a link, a name to contact, a document they asked for. It keeps only the ones that never went out, orders them by whoever you see next, and writes each note for you with the item named and a place left for you to attach it. It works from your own mail alone, never from session recordings, and nothing goes out without you.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"wellness-caseload-drift-watch":{id:"wellness-caseload-drift-watch",agentSlug:"town-wellness-caseload-drift-watch",version:2,name:"Caseload Drift Watch",description:"Monday and Thursday afternoons, compares who you have actually been seeing against what is on the calendar ahead, and names the people whose next appointment quietly stopped being scheduled. Each one is listed with the date you last saw them, how far past their usual rhythm that is, and whether anything in your mail already explains it. It reports and stops there: no message is written, and no reason is guessed.",verified:!0,hidden:!0,requirements:["google"]},"wellness-intake-inquiry-tracker":{id:"wellness-intake-inquiry-tracker",agentSlug:"town-wellness-intake-inquiry-tracker",version:2,name:"Intake Inquiry Tracker",description:"Every weekday morning, gathers the people who wrote asking about working with you and places each one at the step it actually reached: never answered, answered and gone quiet, consult on the calendar, consult done with nothing booked, paperwork out, or booked. It keeps one private log of the whole queue and names the ones where the next move is yours. It writes those replies and leaves them unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"wellness-open-slot-backfill":{id:"wellness-open-slot-backfill",agentSlug:"town-wellness-open-slot-backfill",version:2,name:"Open Slot Backfill",description:"Twice each weekday, rereads the coming weeks of your schedule against the cancellations, reschedules, and no-shows sitting in your mail and calendar, and separates the two cases that look alike: an appointment that simply moved, and an hour that is now genuinely empty. Every empty hour is listed with the people who already asked for that day or time. It writes one offer per opening and leaves it unsent; switch to report-only if you just want the openings.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"wellness-practice-billing-chase":{id:"wellness-practice-billing-chase",agentSlug:"town-wellness-practice-billing-chase",version:2,name:"Practice Billing Chase",description:"On Tuesdays and Fridays, pulls the money threads of the practice out of everything else in the inbox and sorts them by who has to move next: superbills a client asked for and never got, claims sent with no determination back, determinations that came back short or denied, balances past your own aging window, and payer correspondence sitting on your side. It writes one reply per thread and leaves it unsent; switch to report-only if you just want the list.",verified:!0,hidden:!0,requirements:["google"],subagentSlugs:["town-write-in-user-voice"]},"wiki-builder":{id:"wiki-builder",agentSlug:"town-wiki-builder",version:16,name:"Data Wiki Builder",description:"Weaves the user's profile, memories, and researched people into a cross-linked, Wikipedia-style data wiki.",verified:!0,adminOnly:!0,hidden:!0,subagentSlugs:[]},"wiki-catchall":{id:"wiki-catchall",agentSlug:"town-wiki-catchall",version:10,name:"Wiki Catch-all",description:"Each night, has Opus diff the user's full memory store against their built Knowledge wiki and write a single catch-all page capturing every durable preference or fact present in memories but missing from the wiki (standing instructions verbatim, the long tail as memory-search pointers), so nothing is lost when the raw-memory block is replaced by the distilled wiki. Opus is affordable while the flag cohort is admins-only; revisit the model before the cohort widens (v1/v2 ran Sonnet 5; v3 upgraded to Opus 4.8 for the admins-only cohort).",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"wiki-maintainer":{id:"wiki-maintainer",agentSlug:"town-wiki-maintainer",version:19,name:"Wiki Maintainer",description:"Each night, reviews what happened during the user's day and makes small, targeted updates to their existing Knowledge wiki — editing affected pages, adding pages for genuinely new things, and pruning stale ones — without rebuilding the wiki from scratch.",verified:!0,adminOnly:!0,hidden:!0,requirements:[],subagentSlugs:[]},"x-bookmark-butler":{id:"x-bookmark-butler",agentSlug:"town-x-bookmark-butler",version:2,name:"Bookmark Butler",description:"Turns your X bookmark pile into a triaged reading queue: grouped by theme, the takeaway pulled from each post, and the three most worth your full attention flagged.",verified:!0,requirements:["x"]},"x-competitor-pulse":{id:"x-competitor-pulse",agentSlug:"town-x-competitor-pulse",version:3,name:"Competitor Pulse",description:"A Monday-morning brief on the X accounts that matter to your business: what competitors shipped and announced, what key voices said, and what got traction last week.",verified:!0,requirements:["x"]},"x-daily-digest":{id:"x-daily-digest",agentSlug:"town-x-daily-digest",version:3,name:"X Daily Digest",description:"Delivers a one-minute morning read of the X accounts you care about: highest-signal and freshest posts, your mentions folded in, with links to every post.",verified:!0,requirements:["x"]},"x-engage-assist":{id:"x-engage-assist",agentSlug:"town-x-engage-assist",version:2,name:"Engage Assist",description:"Finds the handful of posts each day where your reply would genuinely add something — from the accounts you want to build relationships with — and drafts the reply for you.",verified:!0,requirements:["x"]},"x-mentions-brief":{id:"x-mentions-brief",agentSlug:"town-x-mentions-brief",version:3,name:"Mentions & Reply Brief",description:"A daily brief of who mentioned you and what's being said about you or your company on X — with suggested replies drafted and ready for you to post.",verified:!0,requirements:["x"]},"x-post-ideas":{id:"x-post-ideas",agentSlug:"town-x-post-ideas",version:2,name:"X Post Ideas",description:"Drafts post and thread ideas in your voice each weekday, seeded by what you've been liking, saving, and posting on X — each with a hook and a why-now.",verified:!0,requirements:["x"]},"x-save-to-action":{id:"x-save-to-action",agentSlug:"town-x-save-to-action",version:2,name:"Save-to-Action",description:"Extracts the action items hiding in your X bookmarks and likes — the tool to try, the thread to apply, the person to follow up with — and sends you the delta as a task list.",verified:!0,requirements:["x"]},"x-topic-radar":{id:"x-topic-radar",agentSlug:"town-x-topic-radar",version:3,name:"Topic Radar",description:"Watches the X topics and competitors you name and pings you only when something genuinely notable happens. Silent otherwise. Every item carries a real link.",verified:!0,requirements:["x"]},"x-week-on-x":{id:"x-week-on-x",agentSlug:"town-x-week-on-x",version:2,name:"Your Week on X",description:"A Sunday-evening mirror of your week on X: what you posted and how it landed, what you saved and liked, and which themes pulled your attention.",verified:!0,requirements:["x"]}},n=Object.values(t),i=Object.fromEntries(n.map(e=>[e.agentSlug,e]));Object.values({"town-auto-email-response":{agentSlug:"town-auto-email-response",name:"Auto Email Response",description:"Drafts thoughtful email replies and handles clear scheduling follow-up, including calendar finalization with approval when a meeting is confirmed",version:25,model:"claude-sonnet-4-6"},"town-auto-inbox-labeler":{agentSlug:"town-auto-inbox-labeler",name:"Auto-inbox Triager",description:"Analyzes an email, chooses the best label if needed, and decides whether downstream response handling may be warranted.",version:14,model:"claude-sonnet-4-6"},"town-auto-scheduler":{agentSlug:"town-auto-scheduler",name:"Auto Scheduler",description:"Handles Auto-inbox scheduling follow-up using the durable scheduling-session engine: tracks participants and availability, proposes times, and finalizes a calendar event when a meeting is confirmed (approval policy from parent Auto-inbox settings)",version:32,model:"claude-sonnet-4-6"},"town-briefing-writer":{agentSlug:"town-briefing-writer",name:"Briefing Writer",description:"Writes the morning briefing using all available tools.",version:33,model:"claude-sonnet-4-6"},"town-browser-driver":{agentSlug:"town-browser-driver",name:"Browser Driver",description:"Hidden callable sub-agent (invoked by the Personal Assistant, never scheduled) that completes one multi-step browsing goal in the calling session's hosted browser: reading pages, navigating, scrolling, clicking, and filling forms as the goal requires. It signs the user in itself from the values Town holds for them, asking for anything it is missing inside its activity tile; when sign-in cannot complete it reports sign-in-required at the site's HTTPS origin so the caller relays that. Input: task_prompt with the goal, plus optional context such as the starting URL and what to bring back. Output: a plain-text report written for the calling agent that says whether the goal was completed, what was found or done, and where browsing stopped. When the goal is to buy, it reaches checkout first: a signed-in merchant account with a saved payment method pays on that method, but only after it reports incomplete with the items, total, saved method, and delivery address and the caller invokes it again with the user's confirmation. Logged out or without a saved method, it pays through Town's Link payment tools when Link is connected: it reports link-approval-required with the user's Link approval link, and once the caller invokes it again with the approved attempt id it issues the one-time card, fills it, and places the order.",version:74,model:"gpt-6.1-sol"},"town-email-criteria-triager":{agentSlug:"town-email-criteria-triager",name:"Email Criteria Triager",description:"Judges an email against a list of natural-language criteria and returns an independent verdict per criterion.",version:2,model:"claude-sonnet-4-6"},"town-general-purpose":{agentSlug:"town-general-purpose",name:"General Purpose",description:"Handles complex multi-step tasks delegated from a parent routine.",version:12,model:"claude-opus-5"},"town-guest-brief-writer":{agentSlug:"town-guest-brief-writer",name:"Guest Brief Writer",description:"Writes the attendee-safe guest briefing for one meeting from allowlisted meeting-shared inputs only.",version:3},"town-research-person":{agentSlug:"town-research-person",name:"Research Person",description:"Person research specialist that avoids identity conflation and prioritizes relationship evidence.",version:29,model:"claude-opus-5"},"town-daily-work-summary-researcher":{agentSlug:"town-daily-work-summary-researcher",name:"Daily Work Summary Researcher",description:"Searches and analyzes emails for a specific connected account for important emails.",version:8,model:"claude-sonnet-4-6"},"town-scheduling-ask":{agentSlug:"town-scheduling-ask",name:"Scheduling Ask",description:"The tool-starved ask-sub-routine for not-inline scheduling escalations (E7). Reads one counterparty message and asks the owner a question — its only capability in the world is notifying them.",version:2,model:"claude-sonnet-4-6"},"town-scheduling-drafter":{agentSlug:"town-scheduling-drafter",name:"Scheduling Drafter",description:"Composes the body of one scheduling email from a code-built Brief. Zero tools (OD-31): it never sees the driver's context, only the fields on Brief.",version:9,model:"claude-sonnet-4-6"},"town-scheduling-reconciler":{agentSlug:"town-scheduling-reconciler",name:"Scheduling Reconciler",description:"Reconciles scheduling-engine session state with what the user manually did over email — records proposals and responses, silently starts or reschedules an effort when none is tracked yet, never drafts or sends anything.",version:14,model:"claude-sonnet-4-6"},"town-scheduling-signal-extractor":{agentSlug:"town-scheduling-signal-extractor",name:"Scheduling Signal Extractor",description:"Extracts a bounded, typed scheduling signal from a counterparty's new reply — never a mechanical meeting change, never raw prose.",version:8,model:"claude-sonnet-4-6"},"town-suggestions-v3-source-researcher":{agentSlug:"town-suggestions-v3-source-researcher",name:"Suggestions Source Researcher",description:"Researches one runtime-selected source for Suggestions V3 using an exact read-only tool profile.",version:1,model:"claude-sonnet-4-6"},"town-write-in-user-voice":{agentSlug:"town-write-in-user-voice",name:"Write in User Voice",description:"Hidden callable sub-agent (invoked by other agents, never scheduled) that rewrites or composes a message so it sounds like the user, for any surface (email, Slack, LinkedIn, X, docs). Grounds the voice in the recipient's person wiki profile, the user's own real prior writing (to that recipient / on that surface), and the user's profile voice section, then returns a JSON object with the styled text, a provenance note naming the sources it used, and a thin-grounding flag. Holds no send or write tools — the calling agent performs the actual write. Input and output contract: see the invoke_routine description.",version:15,model:"claude-opus-5"}}),e.s(["STOCK_AGENT_CATALOG",0,t,"STOCK_AGENT_CATALOG_BY_SLUG",0,i,"STOCK_AGENT_CATALOG_LIST",0,n])}]);

//# debugId=747a40f4-87bf-6b99-897f-771419d33ad1